/// The signed-in session held in client memory. Cleared on sign-out and absent
/// during server rendering, so protected screens render their signed-out state
/// until the browser establishes a session.
#[derive(Clone, PartialEq)]
struct Session {
    access_token: String,
    /// Rotating refresh token, mirrored into browser storage so a reload can
    /// restore the session instead of silently signing the user out.
    refresh_token: Option<String>,
    user: IdentityUser,
}

#[derive(Clone, Debug, PartialEq, Routable)]
#[rustfmt::skip]
/// Three-tier, sector-scoped routing per [01 · Layout & Flow].
///
/// `/s/:sector/…` is workspace scope (`:sector` is a slug, so the URL carries the
/// scope and a link is shareable) · `/org/…` is the cross-sector roll-up ·
/// `/admin/…` is governance. Auth and personal screens stay unscoped. Story and
/// article ids are globally unique, so the editor and reader keep flat paths.
enum Route {
    #[layout(Shell)]
        // --- personal / auth (no scope) ---
        #[route("/sign-in")]
        SignIn {},
        #[route("/forgot-password")]
        ForgotPassword {},
        #[route("/invitations")]
        Invitations {},
        #[route("/settings")]
        Settings {},
        #[route("/notifications")]
        NotificationCenter {},
        #[route("/settings/notifications")]
        NotificationSettings {},
        #[route("/settings/sessions")]
        SessionSettings {},
        #[route("/settings/following")]
        Following {},

        // --- org scope: cross-sector roll-ups ---
        #[route("/")]
        Dashboard {},
        #[route("/org/sectors")]
        Workspaces {},
        #[route("/org/search")]
        SearchResults {},
        #[route("/org/feed")]
        Feed {},
        #[route("/org/pitches")]
        Pitches {},
        #[route("/org/intake")]
        EditorialIntake {},
        #[route("/org/pitches/:pitch_id/review")]
        PitchReview { pitch_id: String },
        #[route("/org/my-pitches")]
        MyPitches {},
        #[route("/org/pitches/:pitch_id/handoff")]
        CommissionHandoff { pitch_id: String },
        #[route("/org/people")]
        Team {},
        #[route("/people/:user_id")]
        PersonProfile { user_id: String },
        #[route("/admin/people/:user_id")]
        AdminUserConsole { user_id: String },
        #[route("/org/analytics")]
        Analytics {},
        #[route("/org/legal")]
        LegalDocs {},
        #[route("/org/assets")]
        Assets {},
        #[route("/org/publishing")]
        Publishing {},
        #[route("/org/publishing/corrections")]
        CorrectionsLedger {},
        #[route("/org/frontpage")]
        FrontPage {},

        // --- sector scope: one instance of each screen per workspace ---
        #[route("/s/:sector")]
        SectorDashboard { sector: String },
        #[route("/s/:sector/stories")]
        Stories { sector: String },
        #[route("/s/:sector/tasks")]
        TasksBoard { sector: String },
        #[route("/s/:sector/planning")]
        Planning { sector: String },
        #[route("/s/:sector/settings")]
        SectorSettings { sector: String },
        // "Every functional screen must exist once per sector" (01 §2, Area 3) —
        // these four existed only as one global screen each.
        #[route("/s/:sector/assets")]
        SectorAssets { sector: String },
        #[route("/s/:sector/team")]
        SectorTeam { sector: String },
        #[route("/s/:sector/analytics")]
        SectorAnalytics { sector: String },
        #[route("/s/:sector/search")]
        SectorSearch { sector: String },
        #[route("/s/:sector/stories/:id/review")]
        ReviewConsole { sector: String, id: String },
        #[route("/s/:sector/stories/:id/verify")]
        VerificationConsole { sector: String, id: String },
        #[route("/s/:sector/stories/:id/publish")]
        PublishingConsole { sector: String, id: String },

        // --- globally-addressed documents ---
        #[route("/story/:id")]
        StoryEditor { id: String },
        #[route("/story/:id/write")]
        StoryWrite { id: String },
        #[route("/read/:slug")]
        Article { slug: String },
        #[route("/standards")]
        EditorialStandards {},
        #[route("/editor")]
        Editor {},

        // --- governance ---
        #[route("/admin")]
        Admin {},
        #[route("/admin/roles")]
        RolesAdmin {},
        #[route("/admin/governance")]
        Governance {},
        #[route("/admin/webhooks")]
        WebhooksAdmin {},
        #[route("/admin/sectors")]
        SectorAdmin {},
        #[route("/admin/sectors/:sector_id")]
        SectorMembers { sector_id: String },
        #[route("/admin/sectors/:sector_id/profile")]
        SectorProfile { sector_id: String },
        #[route("/admin/sector-applications")]
        SectorApplications {},
        #[route("/sectors/browse")]
        SectorBrowse {},
        #[route("/sectors/:sector_id/apply?:role")]
        ApplyToSectorPage { sector_id: String, role: String },
        #[route("/my/applications")]
        MyApplications {},

        // Signed in, zero memberships (01 §2, Area 1).
        #[route("/no-access")]
        NoAccess {},
    #[route("/onboarding")]
    Onboarding {},
    #[route("/:..segments")]
    NotFound { segments: Vec<String> },
}

