/// The sectors the signed-in user may operate in, plus which one is active.
///
/// This replaces the hardcoded decorative desk list. `active` is an index into
/// `sectors`; `None` means the org-wide ("All sectors") view.
#[derive(Clone, Default, PartialEq)]
struct SectorScope {
    sectors: Vec<api::SectorView>,
    active: Option<usize>,
    loaded: bool,
}

impl SectorScope {
    fn current(&self) -> Option<&api::SectorView> {
        self.active.and_then(|index| self.sectors.get(index))
    }

    /// The active workspace's desk id, for resolving its brand. `None` (no active
    /// sector) resolves to the org/platform default brand.
    fn brand_desk_id(&self) -> Option<String> {
        self.current().map(|sector| sector.id.clone())
    }

    /// The desk id behind a URL slug. `None` means the viewer holds no membership
    /// in that sector — the screens render a no-access state rather than an empty
    /// one, so an unpermitted link is never mistaken for an empty workspace.
    fn id_for_slug(&self, slug: &str) -> Option<String> {
        self.sectors
            .iter()
            .find(|sector| sector.slug == slug)
            .map(|sector| sector.id.clone())
    }

    /// The active sector's slug, for building sector-scoped nav links.
    fn active_slug(&self) -> Option<String> {
        self.current().map(|sector| sector.slug.clone())
    }
}

/// The capability keys the signed-in viewer holds **at org level**, resolved once
/// from the very engine the server enforces with (`/effective-permissions`, self).
///
/// Nav uses this to stop offering doors that would 403 — presentation only; every
/// endpoint behind a link is independently gated server-side. Org-scoped on
/// purpose: a desk-scoped grant does not surface here, so this may gate only
/// org-wide destinations (the Newsroom roll-ups and Admin). Sector nav is
/// membership-scoped and left to the server, never hidden by this set — otherwise a
/// desk-scoped editor would lose their own tools.
#[derive(Clone, Default, PartialEq)]
struct Capabilities {
    keys: std::collections::HashSet<String>,
}

impl Capabilities {
    /// Whether the viewer holds `capability` at org level.
    fn can(&self, capability: &str) -> bool {
        self.keys.contains(capability)
    }

    /// Whether the viewer holds any of `capabilities` at org level.
    fn can_any(&self, capabilities: &[&str]) -> bool {
        capabilities.iter().any(|capability| self.keys.contains(*capability))
    }
}

/// Live-change signal from the server's SSE stream.
///
/// The server publishes a change *type* and never row data ("invalidate, never
/// patch" — see `realtime.rs`), so this holds one counter per type. A screen reads
/// the counter for what it displays inside its `use_resource`; the read registers
/// the dependency, and a bump refetches from the server, which stays the authority
/// on what actually changed.
///
/// `connected` is the real connection state, not a decoration: the cosmetic "Live"
/// dot was removed during Phase 0 precisely because it implied a connection that
/// did not exist. This one is set from `onopen`/`onerror`.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
struct Realtime {
    connected: bool,
    stories: u32,
    tasks: u32,
    reviews: u32,
    releases: u32,
    feed: u32,
}

impl Realtime {
    /// The counter for one change type. An unknown type returns 0 — a new emit
    /// vocabulary on the server is inert here rather than a panic.
    const fn tick(self, channel: &str) -> u32 {
        match channel.as_bytes() {
            b"stories" => self.stories,
            b"tasks" => self.tasks,
            b"reviews" => self.reviews,
            b"releases" => self.releases,
            b"feed" => self.feed,
            _ => 0,
        }
    }

    fn bump(&mut self, channel: &str) {
        match channel {
            "stories" => self.stories = self.stories.wrapping_add(1),
            "tasks" => self.tasks = self.tasks.wrapping_add(1),
            "reviews" => self.reviews = self.reviews.wrapping_add(1),
            "releases" => self.releases = self.releases.wrapping_add(1),
            "feed" => self.feed = self.feed.wrapping_add(1),
            _ => {}
        }
    }
}

/// Opens the SSE stream and forwards each change type into the [`Realtime`]
/// context.
///
/// `EventSource` lives in JS because it cannot carry an `Authorization` header —
/// the token goes in the query string, which is what the server's `events_stream`
/// expects — and the bridge back into Dioxus is `dioxus.send` / `Eval::recv`. The
/// stream is torn down and reopened whenever the session changes so a signed-out
/// browser is not left holding an authenticated connection.
const REALTIME_JS: &str = r"
    const token = await dioxus.recv();
    if (window.__meridianStream) { window.__meridianStream.close(); }
    const source = new EventSource('/api/v1/events/stream?access_token=' + encodeURIComponent(token));
    window.__meridianStream = source;
    source.onopen = () => dioxus.send('#open');
    source.onerror = () => dioxus.send('#error');
    source.onmessage = (event) => {
        try { dioxus.send(JSON.parse(event.data).type); } catch (_) { /* ignore a malformed frame */ }
    };
";

#[component]
fn App() -> Element {
    let mut session = use_context_provider(|| Signal::new(None::<Session>));
    let mut scope = use_context_provider(|| Signal::new(SectorScope::default()));
    let mut caps = use_context_provider(|| Signal::new(Capabilities::default()));
    // Tracks the initial session restore. Starts `true` so a returning user with a
    // stored token sees a neutral loader — never a flash of the sign-in/lock page —
    // until we know whether they're actually signed in.
    let mut restoring = use_context_provider(|| Signal::new(true));

    // Apply the saved typography scheme on first paint (default "editorial"), so
    // the whole app renders in the chosen faces before anything else draws.
    use_effect(|| {
        #[cfg(feature = "web")]
        {
            let _ = document::eval(&format!(
                "document.documentElement.setAttribute('data-font', {:?});",
                stored_font()
            ));
        }
    });

    // Apply the saved colour theme (or the sepia house default) on first paint, so
    // the whole app renders in the chosen palette before content draws — no flash of
    // the wrong theme on reload, and the default is consistent app-wide.
    use_effect(|| {
        #[cfg(feature = "web")]
        {
            let _ = document::eval(&meridian_ui::boot_theme_script(stored_theme()));
        }
    });

    // Apply the resolved workspace brand over the built-in wire-service tokens:
    // the active workspace's own brand if it has one, else the org/platform
    // default, else nothing (the tokens stand). Re-runs when the sector changes.
    use_effect(move || {
        let desk = scope.read().brand_desk_id();
        spawn(async move {
            match api::get_branding(desk).await {
                Ok(Some(brand)) => {
                    apply_brand(brand.accent_color.as_deref(), brand.ink_color.as_deref());
                }
                _ => apply_brand(None, None),
            }
        });
    });

    // Restore the session from the stored refresh token on first paint. Without
    // this the session lived in memory only, so a reload signed the user out —
    // which makes a permission-gated UI impossible to actually use or verify.
    use_future(move || async move {
        if session.read().is_some() {
            restoring.set(false);
            return;
        }
        let Some(stored) = api::stored_refresh_token() else {
            restoring.set(false);
            return;
        };
        if let Ok((access_token, refresh_token, user)) = api::restore_session(stored).await {
            session.set(Some(Session { access_token, refresh_token, user }));
        }
        restoring.set(false);
    });

    // Subscribe to server-sent changes for as long as there is a session. The
    // emit points already existed on every mutation site; this is the consumer
    // they never had.
    let mut realtime = use_context_provider(|| Signal::new(Realtime::default()));
    use_effect(move || {
        let token = session.read().as_ref().map(|s| s.access_token.clone());
        spawn(async move {
            let Some(token) = token else {
                realtime.set(Realtime::default());
                return;
            };
            let mut stream = document::eval(REALTIME_JS);
            if stream.send(token).is_err() {
                return;
            }
            // Ends when the eval is dropped — which happens when the session
            // changes and this effect re-runs.
            while let Ok(message) = stream.recv::<String>().await {
                match message.as_str() {
                    "#open" => realtime.write().connected = true,
                    "#error" => realtime.write().connected = false,
                    channel => realtime.write().bump(channel),
                }
            }
            realtime.write().connected = false;
        });
    });

    // Load the viewer's sectors whenever a session appears. The server already
    // filters to their memberships, so whatever arrives is exactly what they may
    // switch between.
    use_effect(move || {
        let token = session.read().as_ref().map(|s| s.access_token.clone());
        spawn(async move {
            match token {
                Some(token) => {
                    let sectors = api::my_sectors(token).await.unwrap_or_default();
                    let active = (!sectors.is_empty()).then_some(0);
                    scope.set(SectorScope { sectors, active, loaded: true });
                }
                None => scope.set(SectorScope::default()),
            }
        });
    });

    // Resolve the viewer's own org-level capabilities whenever a session appears,
    // from the same authorization engine the server enforces with. The nav reads
    // this to hide org-wide doors that would 403 — never as the security boundary,
    // which stays on the server. An admin resolves to every capability allowed.
    use_effect(move || {
        let creds = session
            .read()
            .as_ref()
            .map(|s| (s.access_token.clone(), s.user.id.clone()));
        spawn(async move {
            match creds {
                Some((token, user_id)) => match api::effective_permissions(token, user_id, None).await {
                    Ok(effective) => {
                        let keys = effective
                            .permissions
                            .into_iter()
                            .filter(|decision| decision.allowed)
                            .map(|decision| decision.capability)
                            .collect();
                        caps.set(Capabilities { keys });
                    }
                    // On failure, fall back to "no org caps": the sidebar still trusts
                    // the session's admin flag for the Admin zone, and every other
                    // door is enforced server-side regardless.
                    Err(_) => caps.set(Capabilities::default()),
                },
                None => caps.set(Capabilities::default()),
            }
        });
    });

    rsx! {
        // Tokens first, then the adapter, then the app sheet: later rules win, so
        // the app can still override a token-derived default.
        document::Link { rel: "stylesheet", href: meridian_ui::TOKENS_CSS }
        document::Link { rel: "stylesheet", href: meridian_ui::DX_ADAPTER_CSS }
        document::Link { rel: "stylesheet", href: MAIN_CSS }
        document::Link { rel: "stylesheet", href: QUILL_CSS }
        document::Script { src: QUILL_JS }
        document::Script { src: QUILLMD_JS }
        document::Script { src: MARKED_JS }
        document::Link { rel: "preconnect", href: "https://fonts.googleapis.com" }
        document::Link { rel: "stylesheet", href: FONTS }
        document::Title { "{brand::name()} — {brand::subtitle()}" }
        document::Link { rel: "icon", r#type: "image/svg+xml", href: FAVICON }
        Router::<Route> {}
    }
}

/// Whether the mobile nav drawer is open. Shared between the topbar (which toggles
/// it), the sidebar (which slides in), the backdrop, and the nav items (which close
/// it on navigation). A no-op on desktop, where the sidebar is always visible.
#[derive(Clone, Copy)]
struct DrawerOpen(Signal<bool>);


/// On client-side navigation a SPA leaves keyboard focus wherever it was (often the
/// nav link just clicked), so screen-reader and keyboard users are never told the
/// page changed. Moving focus to the `tabindex=-1` main region resets the reading
/// position to the top of the new content — the standard accessible-router pattern.
const ROUTE_FOCUS_JS: &str = "const m=document.getElementById('main-content');if(m){m.focus();}";

/// Wires a `.mtabs` block for native mobile swipe-tabs: tapping a segmented
/// button smooth-scrolls its panel into view, and an IntersectionObserver marks
/// the active pill as the user swipes the scroll-snap track. Idempotent per
/// track (guarded by a data flag). `%ID%` is replaced with the track element id.
const MTABS_JS: &str = r#"(function(id){
  const track=document.getElementById(id); if(!track||track.dataset.mtInit) return; track.dataset.mtInit='1';
  const bar=track.parentElement&&track.parentElement.querySelector('.mtabs-bar');
  const links=bar?Array.prototype.slice.call(bar.querySelectorAll('.mtabs-tab')):[];
  const setActive=function(pid){links.forEach(function(a){a.classList.toggle('is-active', a.getAttribute('href')==='#'+pid);});};
  // The anchor's native hash navigation drives which panel shows (:target); we
  // only mirror it on the active pill. No preventDefault, so vertical scrolling
  // is never captured by a horizontal scroller.
  links.forEach(function(a){a.addEventListener('click',function(){setActive(a.getAttribute('href').slice(1));});});
  var panels=track.querySelectorAll('.mtabs-panel');
  var cur=location.hash?location.hash.slice(1):(panels[0]?panels[0].id:'');
  if(cur) setActive(cur);
})('%ID%');"#;

#[component]
fn Shell() -> Element {
    let session = use_context::<Signal<Option<Session>>>();
    let restoring = use_context::<Signal<bool>>();
    let signed_in = session.read().is_some();
    let drawer = use_context_provider(|| DrawerOpen(Signal::new(false)));
    let mut open = drawer.0;

    // Re-focus main on every route change. `use_reactive` reruns the effect only
    // when the route actually changes; the first-paint guard skips the initial
    // mount, where no navigation has happened and stealing focus would be wrong.
    let route = use_route::<Route>();
    let mut first_paint = use_signal(|| true);
    use_effect(use_reactive!(|(route,)| {
        let _ = route;
        if *first_paint.peek() {
            first_paint.set(false);
        } else {
            document::eval(ROUTE_FOCUS_JS);
        }
    }));

    rsx! {
        a { class: "skip-link", href: "#main-content", "Skip to main content" }
        if signed_in {
            div { class: "app-layout",
                Sidebar {}
                div {
                    class: if open() { "drawer-backdrop is-open" } else { "drawer-backdrop" },
                    onclick: move |_| open.set(false),
                }
                div { class: "main-area",
                    CommandPalette {}
                    Topbar {}
                    main { id: "main-content", tabindex: "-1", class: "content",
                        SuspenseBoundary {
                            fallback: |_: SuspenseContext| rsx! { p { class: "state", "Loading…" } },
                            Outlet::<Route> {}
                        }
                    }
                    nav { class: "botnav", aria_label: "Primary",
                        Link { to: Route::Dashboard {}, class: "botnav-i", active_class: "is-active",
                            span { class: "botnav-ic", Icon { name: "dashboard" } } span { class: "botnav-l", "Home" } }
                        Link { to: Route::Feed {}, class: "botnav-i", active_class: "is-active",
                            span { class: "botnav-ic", Icon { name: "feed" } } span { class: "botnav-l", "Feed" } }
                        Link { to: Route::Pitches {}, class: "botnav-i", active_class: "is-active",
                            span { class: "botnav-ic", Icon { name: "stories" } } span { class: "botnav-l", "Pitches" } }
                        Link { to: Route::Team {}, class: "botnav-i", active_class: "is-active",
                            span { class: "botnav-ic", Icon { name: "team" } } span { class: "botnav-l", "People" } }
                        Link { to: Route::SearchResults {}, class: "botnav-i", active_class: "is-active",
                            span { class: "botnav-ic", Icon { name: "search" } } span { class: "botnav-l", "Search" } }
                    }
                }
            }
        } else if restoring() {
            // A stored session is being restored — show a neutral loader, never the
            // sign-in/lock page, so a returning user isn't wrongly shown auth.
            div { class: "boot-screen",
                div { class: "boot-mark",
                    img { class: "brand-img brand-mark-light", src: BRAND_MARK, alt: "{brand::name()}" }
                    img { class: "brand-img brand-mark-dark", src: BRAND_MARK_DARK, alt: "" }
                }
                p { class: "boot-text", "Restoring your session\u{2026}" }
            }
        } else {
            main { id: "main-content", tabindex: "-1",
                SuspenseBoundary {
                    fallback: |_: SuspenseContext| rsx! { p { class: "state", "Loading…" } },
                    Outlet::<Route> {}
                }
            }
        }
    }
}

/// Inline lucide-style line icons, so the chrome matches the React app without an
/// icon dependency.
#[component]
fn Icon(name: &'static str) -> Element {
    use crate::icons::lucide;
    // Maps the app's semantic icon names to vendored Iconify (Lucide) glyphs —
    // modern, consistent line icons. Add a new glyph with
    // `dioxus-iconify --output crates/web/src/icons add lucide:<name>`.
    let data = match name {
        "dashboard" => lucide::LayoutDashboard,
        "workspaces" => lucide::Boxes,
        "stories" => lucide::Newspaper,
        "editor" => lucide::SquarePen,
        "tasks" => lucide::ListChecks,
        "team" => lucide::Users,
        "feed" => lucide::Rss,
        "calendar" => lucide::CalendarDays,
        "analytics" => lucide::ChartColumn,
        "assets" => lucide::Images,
        "invitations" => lucide::Mail,
        "admin" => lucide::ShieldCheck,
        "settings" => lucide::Settings,
        "search" => lucide::Search,
        "bell" => lucide::Bell,
        "plus" => lucide::Plus,
        "grid" => lucide::LayoutGrid,
        "user" => lucide::User,
        "lock" => lucide::Lock,
        "check" => lucide::Check,
        "eye" => lucide::Eye,
        "x" => lucide::X,
        "description" => lucide::AlignLeft,
        "document" => lucide::FileText,
        "image" => lucide::Image,
        "verification" => lucide::BadgeCheck,
        _ => lucide::LayoutGrid,
    };
    rsx! {
        // Keep our own svg wrapper (no width/height) so the existing CSS sizing
        // rules drive the glyph size; the vendored `body` already carries
        // `stroke="currentColor"` per path, so it inherits the ink colour.
        svg {
            xmlns: "http://www.w3.org/2000/svg",
            view_box: "{data.view_box}",
            fill: "none",
            // Icons are decorative: the accessible name comes from the adjacent
            // label or the button's own `aria-label`, so hide the glyph from AT and
            // keep it out of the tab order.
            "aria-hidden": "true",
            "focusable": "false",
            dangerous_inner_html: "{data.body}",
        }
    }
}

#[component]
fn Topbar() -> Element {
    let scope = use_context::<Signal<SectorScope>>();
    let realtime = use_context::<Signal<Realtime>>();
    let drawer = use_context::<DrawerOpen>();
    // The breadcrumb must match where you actually are: the sector in the URL when
    // you're inside one, otherwise the route's own zone — never a stale default
    // sector. Same source of truth as the sidebar (`route_zone`), so they can't drift.
    let route = use_route::<Route>();
    let active = route_sector_slug(&route).map_or_else(
        || match route_zone(&route) {
            "newsroom" => "Newsroom".to_owned(),
            "admin" => "Admin".to_owned(),
            _ => "Personal".to_owned(),
        },
        |slug| {
            scope
                .read()
                .sectors
                .iter()
                .find(|sector| sector.slug == slug)
                .map_or(slug, |sector| sector.name.clone())
        },
    );
    let live = realtime.read().connected;
    rsx! {
        header { class: "topbar",
            // Mobile-only menu toggle; hidden on desktop where the sidebar is fixed.
            button {
                class: "hamburger",
                r#type: "button",
                aria_label: "Toggle navigation menu",
                onclick: move |_| {
                    let mut open = drawer.0;
                    let now = open();
                    open.set(!now);
                },
                Icon { name: "grid" }
            }
            // The search box navigates to the real results screen. The "Live" pill
            // is back, but only because it is now real: it reflects the SSE
            // connection's own `onopen`/`onerror`, which is why the decorative
            // version was deleted rather than left in place.
            Link { to: Route::SearchResults {}, class: "searchbar",
                span { class: "ico", Icon { name: "search" } }
                span { "Search stories by headline, dek or category…" }
                span { class: "kbd", "\u{2318}K" }
            }
            div { class: "topbar-actions",
                span { class: "badge", "{active}" }
                span {
                    class: "badge",
                    title: if live {
                        "Connected to the live change stream"
                    } else {
                        "Not connected — screens refresh when you navigate"
                    },
                    style: if live { "background:var(--success);color:#fff" } else { "" },
                    if live { "Live" } else { "Offline" }
                }
                Link { to: Route::NotificationCenter {}, class: "iconbtn", aria_label: "Notifications", Icon { name: "bell" } }
                Link { to: Route::Editor {}, class: "primary",
                    Icon { name: "editor" }
                    "New story"
                }
            }
        }
    }
}


/// The sector switcher — the spine of the workspace model.
///
/// Driven entirely by the viewer's memberships (`GET /api/v1/desks`, filtered
/// server-side by `can_view_desk`). Selecting a sector sets the active scope that
/// sector-aware screens read. Per the UI data policy this renders only backend
/// data, a loading state, or a truthful empty state — never a stand-in desk.
#[component]
fn SectorSwitcher() -> Element {
    let scope = use_context::<Signal<SectorScope>>();
    let snapshot = scope.read().clone();
    // Highlight the sector you're actually looking at (from the URL), not a stored
    // index — so this list and the sector nav above always agree.
    let route = use_route::<Route>();
    let current = route_sector_slug(&route);

    if !snapshot.loaded {
        return rsx! { div { class: "desk-item muted", "Loading sectors…" } };
    }
    if snapshot.sectors.is_empty() {
        return rsx! {
            div { class: "desk-item muted",
                "No sectors yet. An administrator grants access from Sector Admin."
            }
        };
    }

    // The full sector list lives on the Sectors page (as apps), not the sidebar —
    // hundreds of sectors would crowd it. Here we surface only the sector you're in
    // (if any) and a link to browse/switch among them all.
    let count = snapshot.sectors.len();
    rsx! {
        if let Some(slug) = current.clone() {
            {
                let name = snapshot
                    .sectors
                    .iter()
                    .find(|sector| sector.slug == slug)
                    .map_or_else(|| slug.clone(), |sector| sector.name.clone());
                rsx! {
                    button {
                        r#type: "button",
                        class: "desk-item is-active",
                        aria_current: "true",
                        onclick: {
                            let slug = slug.clone();
                            move |_| { navigator().push(Route::SectorDashboard { sector: slug.clone() }); }
                        },
                        span { class: "desk-dot", style: "background:{sector_color(&slug)}" }
                        span { "{name}" }
                    }
                }
            }
        }
        Link { to: Route::Workspaces {}, class: "desk-item",
            span { class: "desk-dot", style: "background:var(--accent-brand)" }
            span { "Browse sectors ({count})" }
        }
    }
}

/// A compact read-only list of the viewer's sectors, reused wherever a screen
/// wants to show "the desks" without inventing any.
#[component]
fn SectorRail() -> Element {
    let scope = use_context::<Signal<SectorScope>>();
    let snapshot = scope.read().clone();

    if !snapshot.loaded {
        return rsx! { p { class: "muted", style: "font-size:.85rem", "Loading sectors…" } };
    }
    if snapshot.sectors.is_empty() {
        return rsx! { p { class: "muted", style: "font-size:.85rem", "No sectors yet." } };
    }
    rsx! {
        ul { class: "rowlist",
            for sector in snapshot.sectors.iter() {
                li { key: "{sector.id}", class: "rowitem",
                    span { class: "desk-dot", style: "background:{sector_color(&sector.slug)}" }
                    Link {
                        to: Route::SectorDashboard { sector: sector.slug.clone() },
                        class: "grow",
                        style: "font-weight:600",
                        "{sector.name}"
                    }
                }
            }
        }
    }
}

/// Installs the ⌘K / Ctrl-K listener.
///
/// Keyboard events only bubble to an element that is an ancestor of the focused
/// node, and focus normally sits on `body` — which is a *parent* of the app root,
/// not a child. So a plain `onkeydown` on the shell misses the shortcut whenever
/// nothing inside the app is focused. This installs a real document-level listener
/// and bridges back into Dioxus by clicking a hidden button, which is the one
/// thing both sides already agree on.
const COMMAND_PALETTE_HOTKEY_JS: &str = r"
if (!window.__meridianCmdK) {
  window.__meridianCmdK = true;
  document.addEventListener('keydown', function (event) {
    const combo = (event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k';
    if (!combo) { return; }
    event.preventDefault();
    const trigger = document.getElementById('cmdk-trigger');
    if (trigger) { trigger.click(); }
  });
}
";

/// One thing the palette can jump to or do.
#[derive(Clone, PartialEq)]
struct CommandEntry {
    label: String,
    hint: &'static str,
    route: Route,
}

/// The ⌘K command palette: jump-to plus sector switching.
///
/// Replaces the static `⌘K` chip that was rendered with no behaviour behind it.
/// Entries are built from the viewer's real memberships, so the palette can never
/// offer a sector they cannot reach — it inherits the same boundary the nav does
/// rather than re-deriving one.
#[component]
fn CommandPalette() -> Element {
    let scope = use_context::<Signal<SectorScope>>();
    let navigator = use_navigator();
    let mut open = use_signal(|| false);
    let mut query = use_signal(String::new);
    let mut cursor = use_signal(|| 0_usize);

    use_effect(move || {
        document::eval(COMMAND_PALETTE_HOTKEY_JS);
    });

    let snapshot = scope.read().clone();
    let mut entries: Vec<CommandEntry> = vec![
        CommandEntry { label: "Home".into(), hint: "Go", route: Route::Dashboard {} },
        CommandEntry { label: "Your sectors".into(), hint: "Go", route: Route::Workspaces {} },
        CommandEntry { label: "Search".into(), hint: "Go", route: Route::SearchResults {} },
        CommandEntry { label: "Newsroom feed".into(), hint: "Go", route: Route::Feed {} },
        CommandEntry { label: "New story".into(), hint: "Create", route: Route::Editor {} },
        CommandEntry { label: "Publishing queue".into(), hint: "Go", route: Route::Publishing {} },
        CommandEntry { label: "Front page".into(), hint: "Go", route: Route::FrontPage {} },
        CommandEntry {
            label: "Corrections ledger".into(),
            hint: "Go",
            route: Route::CorrectionsLedger {},
        },
        CommandEntry { label: "Sector registry".into(), hint: "Admin", route: Route::SectorAdmin {} },
        CommandEntry { label: "Roles & permissions".into(), hint: "Admin", route: Route::RolesAdmin {} },
        CommandEntry { label: "Governance".into(), hint: "Admin", route: Route::Governance {} },
        CommandEntry { label: "Settings".into(), hint: "Go", route: Route::Settings {} },
        CommandEntry { label: "Sessions".into(), hint: "Account", route: Route::SessionSettings {} },
        CommandEntry { label: "Following".into(), hint: "Account", route: Route::Following {} },
    ];
    // Per-sector entries, so the palette can reach any screen in any sector the
    // viewer belongs to — the whole point of a sector-scoped IA.
    for sector in &snapshot.sectors {
        entries.push(CommandEntry {
            label: format!("Switch to {}", sector.name),
            hint: "Sector",
            route: Route::SectorDashboard { sector: sector.slug.clone() },
        });
        for (suffix, route) in [
            ("stories", Route::Stories { sector: sector.slug.clone() }),
            ("tasks", Route::TasksBoard { sector: sector.slug.clone() }),
            ("planning", Route::Planning { sector: sector.slug.clone() }),
            ("search", Route::SectorSearch { sector: sector.slug.clone() }),
            ("assets", Route::SectorAssets { sector: sector.slug.clone() }),
            ("team", Route::SectorTeam { sector: sector.slug.clone() }),
            ("analytics", Route::SectorAnalytics { sector: sector.slug.clone() }),
            ("settings", Route::SectorSettings { sector: sector.slug.clone() }),
        ] {
            entries.push(CommandEntry {
                label: format!("{} · {suffix}", sector.name),
                hint: "Sector",
                route,
            });
        }
    }

    let term = query().to_lowercase();
    let matches: Vec<CommandEntry> = entries
        .into_iter()
        .filter(|entry| term.is_empty() || entry.label.to_lowercase().contains(&term))
        .collect();
    let count = matches.len();

    let mut go = move |route: Route| {
        open.set(false);
        query.set(String::new());
        cursor.set(0);
        navigator.push(route);
    };

    rsx! {
        // The bridge the hotkey listener clicks. Kept focusable-but-invisible
        // rather than display:none, which would make it unclickable.
        button {
            id: "cmdk-trigger",
            r#type: "button",
            "aria-hidden": "true",
            tabindex: "-1",
            style: "position:absolute;width:1px;height:1px;opacity:0;pointer-events:none",
            onclick: move |_| {
                let next = !open();
                open.set(next);
                if next {
                    query.set(String::new());
                    cursor.set(0);
                }
            },
        }
        if open() {
            div {
                class: "cmdk-backdrop",
                role: "presentation",
                onclick: move |_| open.set(false),
                div {
                    class: "cmdk-panel",
                    role: "dialog",
                    "aria-modal": "true",
                    "aria-label": "Command palette",
                    onclick: move |event| event.stop_propagation(),
                    input {
                        class: "cmdk-input",
                        r#type: "text",
                        autofocus: true,
                        placeholder: "Jump to a screen or sector…",
                        value: "{query}",
                        oninput: move |event| {
                            query.set(event.value());
                            cursor.set(0);
                        },
                        onkeydown: move |event| {
                            match event.key() {
                                Key::Escape => open.set(false),
                                // The input is the dialog's only focusable element, so
                                // trap Tab here — otherwise focus escapes into the
                                // obscured background. Escape remains the way out.
                                Key::Tab => event.prevent_default(),
                                Key::ArrowDown => {
                                    event.prevent_default();
                                    if count > 0 {
                                        cursor.set((cursor() + 1) % count);
                                    }
                                }
                                Key::ArrowUp => {
                                    event.prevent_default();
                                    if count > 0 {
                                        cursor.set((cursor() + count - 1) % count);
                                    }
                                }
                                Key::Enter => {
                                    event.prevent_default();
                                    if let Some(entry) = matches.get(cursor()) {
                                        go(entry.route.clone());
                                    }
                                }
                                _ => {}
                            }
                        },
                    }
                    if matches.is_empty() {
                        p { class: "muted", style: "padding:.7rem", "Nothing matches." }
                    } else {
                        ul { class: "cmdk-list", role: "listbox",
                            for (index, entry) in matches.iter().enumerate() {
                                li {
                                    key: "{entry.hint}-{entry.label}",
                                    role: "option",
                                    "aria-selected": if index == cursor() { "true" } else { "false" },
                                    class: if index == cursor() { "cmdk-item is-active" } else { "cmdk-item" },
                                    onclick: {
                                        let route = entry.route.clone();
                                        move |_| go(route.clone())
                                    },
                                    span { class: "grow", "{entry.label}" }
                                    span { class: "muted", style: "font-size:.75rem", "{entry.hint}" }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

/// Channel kinds, mirroring `CHANNEL_KINDS` in `crates/newsroom/src/media.rs` and
/// the `channels_kind_check` constraint in migration `0020`.
const CHANNEL_KINDS: [&str; 5] = ["web", "app_push", "newsletter", "social", "syndication"];

/// The audit-log entity filters offered on the governance screen. The backend
/// accepts any entity type; these are the ones the domain actually writes.
const AUDIT_ENTITIES: [&str; 8] = [
    "story",
    "task",
    "release",
    "correction",
    "claim",
    "desk",
    "user",
    "delegation",
];

/// `/admin/governance` — the audit trail, permission policies, delegations and
/// feature flags.
///
/// These four are the governance half of `admin.rs` and `nav.rs`: all finished,
/// all previously unreachable. The audit log in particular is the record that
/// makes every other screen accountable — without it, "who changed this?" had no
/// answer anywhere in the product.
#[component]
fn Governance() -> Element {
    let session = use_context::<Signal<Option<Session>>>();
    let scope = use_context::<Signal<SectorScope>>();
    let mut reload = use_signal(|| 0_u32);
    let mut error = use_signal(|| None::<String>);
    let mut pending = use_signal(|| false);
    let mut entity_filter = use_signal(String::new);

    let audit = use_resource(move || {
        let entity = entity_filter();
        async move {
            reload();
            match session.read().clone() {
                None => Ok(None),
                Some(s) => api::audit_log(s.access_token, Some(entity), 100).await.map(Some),
            }
        }
    });

    let policies = use_resource(move || async move {
        reload();
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::permission_policies(s.access_token).await.map(Some),
        }
    });

    let delegations = use_resource(move || async move {
        reload();
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::delegations(s.access_token).await.map(Some),
        }
    });

    let flags = use_resource(move || async move {
        reload();
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::feature_flags(s.access_token).await.map(Some),
        }
    });

    // Channels: everything, not just active, so a retired one stays manageable.
    let channels = use_resource(move || async move {
        reload();
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::channels(s.access_token, false).await.map(Some),
        }
    });
    let mut channel_key = use_signal(String::new);
    let mut channel_name = use_signal(String::new);
    let mut channel_kind = use_signal(|| "web".to_owned());
    let mut channel_webhook = use_signal(String::new);

    let save_channel = move |event: FormEvent| {
        event.prevent_default();
        if pending() {
            return;
        }
        let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
            return;
        };
        let key = channel_key();
        let name = channel_name();
        if key.trim().is_empty() || name.trim().is_empty() {
            error.set(Some("A channel needs both a key and a name.".to_owned()));
            return;
        }
        let kind = channel_kind();
        let webhook = { let w = channel_webhook(); if w.trim().is_empty() { None } else { Some(w) } };
        pending.set(true);
        error.set(None);
        spawn(async move {
            match api::save_channel(token, key, name, kind, None, true, webhook).await {
                Ok(()) => {
                    channel_key.set(String::new());
                    channel_name.set(String::new());
                    channel_webhook.set(String::new());
                    reload += 1;
                }
                Err(message) => error.set(Some(message)),
            }
            pending.set(false);
        });
    };

    let mut toggle_channel = move |channel: api::ChannelRow| {
        if pending() {
            return;
        }
        let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
            return;
        };
        pending.set(true);
        error.set(None);
        spawn(async move {
            // Upsert by key, flipping only `is_active` — retiring a channel keeps
            // its history, its webhook config, and the receipts that reference it.
            let webhook = channel.webhook_url();
            match api::save_channel(
                token,
                channel.key,
                channel.name,
                channel.kind,
                channel.description,
                !channel.is_active,
                webhook,
            )
            .await
            {
                Ok(()) => reload += 1,
                Err(message) => error.set(Some(message)),
            }
            pending.set(false);
        });
    };

    let people = use_resource(move || async move {
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::users(s.access_token).await.map(Some),
        }
    });

    let capabilities = use_resource(move || async move {
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::capabilities(s.access_token).await.map(Some),
        }
    });

    // Resolves an actor id to a name for the audit and policy tables. Falls back
    // to the raw id rather than hiding it — an unresolvable actor is still
    // evidence, and blanking it would quietly lose the trail.
    let name_of = move |id: &str| -> String {
        match &*people.read_unchecked() {
            Some(Ok(Some(rows))) => rows
                .iter()
                .find(|person| person.id == id)
                .map_or_else(|| id.to_owned(), |person| person.display_name.clone()),
            _ => id.to_owned(),
        }
    };

    let roles = use_resource(move || async move {
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::roles(s.access_token).await.map(Some),
        }
    });

    // --- role assignments ---
    //
    // Assignments are per-person, so the list loads for whoever is selected
    // rather than for everyone — there is no "all assignments" endpoint, and
    // fanning out one request per user would be a worse answer than asking.
    let mut assignment_user = use_signal(String::new);
    let mut assignment_role = use_signal(String::new);
    let mut assignment_sector = use_signal(String::new);
    let mut assignment_until = use_signal(String::new);
    let mut assignment_reason = use_signal(String::new);

    let assignments = use_resource(move || {
        let user = assignment_user();
        async move {
            reload();
            if user.is_empty() {
                return Ok(None);
            }
            match session.read().clone() {
                None => Ok(None),
                Some(s) => api::role_assignments(s.access_token, user).await.map(Some),
            }
        }
    });

    let add_assignment = move |event: FormEvent| {
        event.prevent_default();
        if pending() {
            return;
        }
        let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
            return;
        };
        let user = assignment_user();
        let role = assignment_role();
        if user.is_empty() || role.is_empty() {
            error.set(Some("Choose both a person and a role.".to_owned()));
            return;
        }
        let sector = assignment_sector();
        let sector = if sector.is_empty() { None } else { Some(sector) };
        let until = assignment_until();
        let until = if until.is_empty() { None } else { Some(format!("{until}T23:59:59Z")) };
        let reason = assignment_reason();
        let reason = if reason.trim().is_empty() { None } else { Some(reason) };
        pending.set(true);
        error.set(None);
        spawn(async move {
            match api::assign_role(token, user, role, sector, until, reason).await {
                Ok(()) => {
                    assignment_reason.set(String::new());
                    reload += 1;
                }
                Err(message) => error.set(Some(message)),
            }
            pending.set(false);
        });
    };

    let mut drop_assignment = move |assignment_id: String| {
        if pending() {
            return;
        }
        let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
            return;
        };
        pending.set(true);
        error.set(None);
        spawn(async move {
            match api::revoke_assignment(token, assignment_id).await {
                Ok(()) => reload += 1,
                Err(message) => error.set(Some(message)),
            }
            pending.set(false);
        });
    };

    // --- new policy ---
    let mut policy_subject = use_signal(String::new);
    let mut policy_capability = use_signal(String::new);
    let mut policy_allow = use_signal(|| true);
    let mut policy_reason = use_signal(String::new);

    let add_policy = move |event: FormEvent| {
        event.prevent_default();
        if pending() {
            return;
        }
        let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
            return;
        };
        let subject = policy_subject();
        let capability = policy_capability();
        if subject.is_empty() || capability.is_empty() {
            error.set(Some("Choose both a person and a capability.".to_owned()));
            return;
        }
        let reason = policy_reason();
        let reason = if reason.trim().is_empty() { None } else { Some(reason) };
        let allow = policy_allow();
        pending.set(true);
        error.set(None);
        spawn(async move {
            match api::upsert_policy(token, subject, capability, allow, reason).await {
                Ok(()) => {
                    policy_reason.set(String::new());
                    reload += 1;
                }
                Err(message) => error.set(Some(message)),
            }
            pending.set(false);
        });
    };

    let mut drop_policy = move |policy_id: String| {
        if pending() {
            return;
        }
        let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
            return;
        };
        pending.set(true);
        error.set(None);
        spawn(async move {
            match api::delete_policy(token, policy_id).await {
                Ok(()) => reload += 1,
                Err(message) => error.set(Some(message)),
            }
            pending.set(false);
        });
    };

    // --- new delegation ---
    let mut delegate_to = use_signal(String::new);
    let mut delegate_capability = use_signal(String::new);
    let mut delegate_until = use_signal(String::new);
    let mut delegate_reason = use_signal(String::new);

    let add_delegation = move |event: FormEvent| {
        event.prevent_default();
        if pending() {
            return;
        }
        let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
            return;
        };
        let to = delegate_to();
        let capability = delegate_capability();
        let until = delegate_until();
        if to.is_empty() || capability.is_empty() || until.is_empty() {
            error.set(Some("A delegation needs a person, a capability and an end date.".to_owned()));
            return;
        }
        let reason = delegate_reason();
        let reason = if reason.trim().is_empty() { None } else { Some(reason) };
        pending.set(true);
        error.set(None);
        spawn(async move {
            match api::create_delegation(
                token,
                to,
                vec![capability],
                format!("{until}T23:59:59Z"),
                reason,
            )
            .await
            {
                Ok(()) => {
                    delegate_reason.set(String::new());
                    reload += 1;
                }
                Err(message) => error.set(Some(message)),
            }
            pending.set(false);
        });
    };

    let mut revoke = move |delegation_id: String| {
        if pending() {
            return;
        }
        let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
            return;
        };
        pending.set(true);
        error.set(None);
        spawn(async move {
            match api::revoke_delegation(token, delegation_id).await {
                Ok(()) => reload += 1,
                Err(message) => error.set(Some(message)),
            }
            pending.set(false);
        });
    };

    // --- flags ---
    let mut toggle_flag = move |key: String, enabled: bool| {
        if pending() {
            return;
        }
        let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
            return;
        };
        pending.set(true);
        error.set(None);
        spawn(async move {
            let patch = serde_json::json!({ "enabled": enabled });
            match api::patch_flag(token, key, patch).await {
                Ok(()) => reload += 1,
                Err(message) => error.set(Some(message)),
            }
            pending.set(false);
        });
    };

    let mut kill_flag = move |key: String| {
        if pending() {
            return;
        }
        let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
            return;
        };
        pending.set(true);
        error.set(None);
        spawn(async move {
            match api::emergency_disable_flag(token, key).await {
                Ok(()) => reload += 1,
                Err(message) => error.set(Some(message)),
            }
            pending.set(false);
        });
    };

    rsx! {
        Guard { title: "Governance",
            div { class: "page-head",
                div {
                    p { class: "eyebrow", "Administration" }
                    h1 { class: "page-title", "Governance" }
                    p { class: "page-sub", "The audit trail, permission overrides, delegations and feature flags." }
                }
                div { class: "head-actions",
                    Link { to: Route::RolesAdmin {}, class: "ghost", "Roles & permissions" }
                }
            }

            if let Some(message) = error() {
                p { class: "state error", role: "alert", "{message}" }
            }

            // --- audit trail ---
            div { class: "card", style: "margin-bottom:1rem;padding:1rem",
                div { class: "spread",
                    h3 { style: "margin:0", "Audit trail" }
                    select {
                        value: "{entity_filter}",
                        oninput: move |e| entity_filter.set(e.value()),
                        option { value: "", "Everything" }
                        for entity in AUDIT_ENTITIES {
                            option { key: "{entity}", value: "{entity}", "{entity}" }
                        }
                    }
                }
                match &*audit.read_unchecked() {
                    Some(Ok(Some(rows))) if rows.is_empty() => rsx! {
                        p { class: "state", "No audit entries match this filter." }
                    },
                    Some(Ok(Some(rows))) => rsx! {
                        table { class: "table",
                            thead { tr { th { "When" } th { "Actor" } th { "Action" } th { "Entity" } } }
                            tbody {
                                for entry in rows.iter() {
                                    tr { key: "{entry.id}",
                                        td { class: "muted", style: "font-size:.8rem", "{entry.created_at}" }
                                        td {
                                            match &entry.actor_id {
                                                Some(actor) => rsx! { "{name_of(actor)}" },
                                                None => rsx! { span { class: "muted", "system" } },
                                            }
                                        }
                                        td { span { class: "badge", "{entry.action}" } }
                                        td { class: "muted", style: "font-size:.8rem", "{entry.entity_type} {entry.entity_id}" }
                                    }
                                }
                            }
                        }
                    },
                    Some(Ok(None)) => rsx! { p { class: "state", "Sign in to see the audit trail." } },
                    Some(Err(message)) => rsx! { p { class: "state error", "Could not load the audit trail: {message}" } },
                    None => rsx! { p { class: "state", "Loading the audit trail…" } },
                }
            }

            // --- role assignments ---
            div { class: "card", style: "margin-bottom:1rem;padding:1rem",
                h3 { style: "margin-top:0", "Role assignments" }
                p { class: "muted", style: "font-size:.85rem",
                    "Resolver step 5, and the only grant that can be scoped to a single sector — which is what makes “editor-in-chief, but only in Investigations” expressible."
                }
                div { class: "field", style: "margin-bottom:.6rem",
                    label { r#for: "assignment-user", "Person" }
                    select {
                        id: "assignment-user",
                        value: "{assignment_user}",
                        oninput: move |e| assignment_user.set(e.value()),
                        option { value: "", "Choose someone…" }
                        if let Some(Ok(Some(rows))) = &*people.read_unchecked() {
                            for person in rows.iter() {
                                option { key: "{person.id}", value: "{person.id}", "{person.display_name}" }
                            }
                        }
                    }
                }
                match &*assignments.read_unchecked() {
                    Some(Ok(Some(rows))) if rows.is_empty() => rsx! {
                        p { class: "state", "No role assignments — this person's capabilities come from their base role and memberships." }
                    },
                    Some(Ok(Some(rows))) => rsx! {
                        ul { class: "rowlist",
                            for assignment in rows.iter() {
                                {
                                    let assignment_id = assignment.id.clone();
                                    let sector_name = assignment.scope_id.as_ref().and_then(|id| {
                                        scope.read().sectors.iter().find(|s| s.id == *id).map(|s| s.name.clone())
                                    });
                                    rsx! {
                                        li { key: "{assignment.id}", class: "rowitem",
                                            span { class: "grow",
                                                div { style: "font-weight:600", "{assignment.role_key}" }
                                                div { class: "muted", style: "font-size:.8rem",
                                                    match &sector_name {
                                                        Some(name) => rsx! { "in {name}" },
                                                        None => rsx! { "{assignment.scope_type}" },
                                                    }
                                                }
                                                if let Some(ends) = &assignment.ends_at {
                                                    div { class: "muted", style: "font-size:.8rem", "Until {ends}" }
                                                }
                                                if let Some(reason) = &assignment.reason {
                                                    div { class: "muted", style: "font-size:.8rem", "{reason}" }
                                                }
                                            }
                                            button {
                                                class: "ghost",
                                                r#type: "button",
                                                disabled: pending(),
                                                onclick: move |_| drop_assignment(assignment_id.clone()),
                                                "Revoke"
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    },
                    Some(Err(message)) => rsx! { p { class: "state error", "Could not load assignments: {message}" } },
                    _ => rsx! { p { class: "muted", style: "font-size:.85rem", "Choose someone to see and change their role assignments." } },
                }
                if !assignment_user().is_empty() {
                    form { style: "margin-top:.8rem;border-top:1px solid var(--border);padding-top:.8rem", onsubmit: add_assignment,
                        div { class: "field-grid",
                            div { class: "field",
                                label { r#for: "assignment-role", "Role" }
                                select {
                                    id: "assignment-role",
                                    value: "{assignment_role}",
                                    oninput: move |e| assignment_role.set(e.value()),
                                    option { value: "", "Choose a role…" }
                                    if let Some(Ok(Some(rows))) = &*roles.read_unchecked() {
                                        for role in rows.iter() {
                                            option { key: "{role.key}", value: "{role.key}", "{role.name}" }
                                        }
                                    }
                                }
                            }
                            div { class: "field",
                                label { r#for: "assignment-sector", "Scope" }
                                select {
                                    id: "assignment-sector",
                                    value: "{assignment_sector}",
                                    oninput: move |e| assignment_sector.set(e.value()),
                                    option { value: "", "Newsroom-wide" }
                                    for sector in scope.read().sectors.iter() {
                                        option { key: "{sector.id}", value: "{sector.id}", "Only in {sector.name}" }
                                    }
                                }
                            }
                        }
                        div { class: "field-grid",
                            div { class: "field",
                                label { r#for: "assignment-until", "Ends (optional)" }
                                input {
                                    id: "assignment-until",
                                    r#type: "date",
                                    value: "{assignment_until}",
                                    oninput: move |e| assignment_until.set(e.value()),
                                }
                            }
                            div { class: "field",
                                label { r#for: "assignment-reason", "Reason" }
                                input {
                                    id: "assignment-reason",
                                    r#type: "text",
                                    value: "{assignment_reason}",
                                    oninput: move |e| assignment_reason.set(e.value()),
                                }
                            }
                        }
                        button { class: "primary", r#type: "submit", disabled: pending(), "Assign role" }
                    }
                }
            }

            // --- permission policies ---
            div { class: "card", style: "margin-bottom:1rem;padding:1rem",
                h3 { style: "margin-top:0", "Permission overrides" }
                p { class: "muted", style: "font-size:.85rem",
                    "A policy is resolver step 3 — it decides before any role default, so a deny here outranks every role the person holds."
                }
                match &*policies.read_unchecked() {
                    Some(Ok(Some(rows))) if rows.is_empty() => rsx! {
                        p { class: "state", "No overrides in force — every decision comes from roles and memberships." }
                    },
                    Some(Ok(Some(rows))) => rsx! {
                        ul { class: "rowlist",
                            for policy in rows.iter() {
                                {
                                    let policy_id = policy.id.clone();
                                    rsx! {
                                        li { key: "{policy.id}", class: "rowitem",
                                            span { class: "grow",
                                                div { style: "font-weight:600", "{name_of(&policy.subject_id)}" }
                                                div { class: "muted", style: "font-size:.8rem", "{policy.capability}" }
                                                if let Some(reason) = &policy.reason {
                                                    div { class: "muted", style: "font-size:.8rem", "{reason}" }
                                                }
                                            }
                                            span {
                                                class: "badge",
                                                style: if policy.allow {
                                                    "background:var(--success);color:#fff"
                                                } else {
                                                    "background:var(--warning)"
                                                },
                                                if policy.allow { "allow" } else { "deny" }
                                            }
                                            button {
                                                class: "ghost",
                                                r#type: "button",
                                                disabled: pending(),
                                                onclick: move |_| drop_policy(policy_id.clone()),
                                                "Remove"
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    },
                    Some(Ok(None)) => rsx! { p { class: "state", "Sign in to see overrides." } },
                    Some(Err(message)) => rsx! { p { class: "state error", "Could not load overrides: {message}" } },
                    None => rsx! { p { class: "state", "Loading overrides…" } },
                }
                form { style: "margin-top:.8rem;border-top:1px solid var(--border);padding-top:.8rem", onsubmit: add_policy,
                    div { class: "field-grid",
                        div { class: "field",
                            label { r#for: "policy-subject", "Person" }
                            select {
                                id: "policy-subject",
                                value: "{policy_subject}",
                                oninput: move |e| policy_subject.set(e.value()),
                                option { value: "", "Choose someone…" }
                                if let Some(Ok(Some(rows))) = &*people.read_unchecked() {
                                    for person in rows.iter() {
                                        option { key: "{person.id}", value: "{person.id}", "{person.display_name}" }
                                    }
                                }
                            }
                        }
                        div { class: "field",
                            label { r#for: "policy-capability", "Capability" }
                            select {
                                id: "policy-capability",
                                value: "{policy_capability}",
                                oninput: move |e| policy_capability.set(e.value()),
                                option { value: "", "Choose a capability…" }
                                if let Some(Ok(Some(rows))) = &*capabilities.read_unchecked() {
                                    for capability in rows.iter() {
                                        option { key: "{capability.key}", value: "{capability.key}", "{capability.key}" }
                                    }
                                }
                            }
                        }
                    }
                    div { class: "field", style: "margin-bottom:.6rem",
                        label { r#for: "policy-decision", "Decision" }
                        select {
                            id: "policy-decision",
                            value: if policy_allow() { "allow" } else { "deny" },
                            oninput: move |e| policy_allow.set(e.value() == "allow"),
                            option { value: "allow", "Allow" }
                            option { value: "deny", "Deny" }
                        }
                    }
                    div { class: "field", style: "margin-bottom:.6rem",
                        label { r#for: "policy-reason", "Reason (recorded)" }
                        input {
                            id: "policy-reason",
                            r#type: "text",
                            value: "{policy_reason}",
                            oninput: move |e| policy_reason.set(e.value()),
                        }
                    }
                    button { class: "primary", r#type: "submit", disabled: pending(), "Write override" }
                }
            }

            // --- delegations ---
            div { class: "card", style: "margin-bottom:1rem;padding:1rem",
                h3 { style: "margin-top:0", "Delegations" }
                p { class: "muted", style: "font-size:.85rem",
                    "A time-boxed hand-over of capabilities — for leave cover. The end date is mandatory; a delegation without one is a permanent grant wearing a temporary label."
                }
                match &*delegations.read_unchecked() {
                    Some(Ok(Some(rows))) if rows.is_empty() => rsx! {
                        p { class: "state", "No delegations in force." }
                    },
                    Some(Ok(Some(rows))) => rsx! {
                        ul { class: "rowlist",
                            for delegation in rows.iter() {
                                {
                                    let delegation_id = delegation.id.clone();
                                    let live = delegation.revoked_at.is_none();
                                    rsx! {
                                        li { key: "{delegation.id}", class: "rowitem",
                                            span { class: "grow",
                                                div { style: "font-weight:600",
                                                    "{name_of(&delegation.from_user_id)} → {name_of(&delegation.to_user_id)}"
                                                }
                                                div { class: "muted", style: "font-size:.8rem", "{delegation.capabilities.join(\", \")}" }
                                                div { class: "muted", style: "font-size:.8rem", "Until {delegation.ends_at}" }
                                                if let Some(reason) = &delegation.reason {
                                                    div { class: "muted", style: "font-size:.8rem", "{reason}" }
                                                }
                                            }
                                            if live {
                                                button {
                                                    class: "ghost",
                                                    r#type: "button",
                                                    disabled: pending(),
                                                    onclick: move |_| revoke(delegation_id.clone()),
                                                    "Revoke"
                                                }
                                            } else {
                                                span { class: "badge", "revoked" }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    },
                    Some(Ok(None)) => rsx! { p { class: "state", "Sign in to see delegations." } },
                    Some(Err(message)) => rsx! { p { class: "state error", "Could not load delegations: {message}" } },
                    None => rsx! { p { class: "state", "Loading delegations…" } },
                }
                form { style: "margin-top:.8rem;border-top:1px solid var(--border);padding-top:.8rem", onsubmit: add_delegation,
                    div { class: "field-grid",
                        div { class: "field",
                            label { r#for: "delegate-to", "Delegate to" }
                            select {
                                id: "delegate-to",
                                value: "{delegate_to}",
                                oninput: move |e| delegate_to.set(e.value()),
                                option { value: "", "Choose someone…" }
                                if let Some(Ok(Some(rows))) = &*people.read_unchecked() {
                                    for person in rows.iter() {
                                        option { key: "{person.id}", value: "{person.id}", "{person.display_name}" }
                                    }
                                }
                            }
                        }
                        div { class: "field",
                            label { r#for: "delegate-capability", "Capability" }
                            select {
                                id: "delegate-capability",
                                value: "{delegate_capability}",
                                oninput: move |e| delegate_capability.set(e.value()),
                                option { value: "", "Choose a capability…" }
                                if let Some(Ok(Some(rows))) = &*capabilities.read_unchecked() {
                                    for capability in rows.iter() {
                                        option { key: "{capability.key}", value: "{capability.key}", "{capability.key}" }
                                    }
                                }
                            }
                        }
                    }
                    div { class: "field-grid",
                        div { class: "field",
                            label { r#for: "delegate-until", "Ends" }
                            input {
                                id: "delegate-until",
                                r#type: "date",
                                value: "{delegate_until}",
                                oninput: move |e| delegate_until.set(e.value()),
                            }
                        }
                        div { class: "field",
                            label { r#for: "delegate-reason", "Reason" }
                            input {
                                id: "delegate-reason",
                                r#type: "text",
                                value: "{delegate_reason}",
                                oninput: move |e| delegate_reason.set(e.value()),
                            }
                        }
                    }
                    button { class: "primary", r#type: "submit", disabled: pending(), "Delegate" }
                }
            }

            // --- distribution channels ---
            div { class: "card", style: "margin-bottom:1rem;padding:1rem",
                h3 { style: "margin-top:0", "Distribution channels" }
                p { class: "muted", style: "font-size:.85rem",
                    "What a release can target. Releases record the channel key, so a key must not change once anything has published to it — retire a channel instead of renaming its key."
                }
                match &*channels.read_unchecked() {
                    Some(Ok(Some(rows))) if rows.is_empty() => rsx! {
                        p { class: "state", "No channels configured." }
                    },
                    Some(Ok(Some(rows))) => rsx! {
                        ul { class: "rowlist",
                            for channel in rows.iter() {
                                {
                                    let row = channel.clone();
                                    rsx! {
                                        li { key: "{channel.id}", class: "rowitem",
                                            span { class: "grow",
                                                div { style: "font-weight:600", "{channel.name}" }
                                                div { class: "muted", style: "font-size:.8rem", "{channel.key} · {status_label(&channel.kind)}" }
                                                if let Some(d) = &channel.description {
                                                    div { class: "muted", style: "font-size:.8rem", "{d}" }
                                                }
                                            }
                                            if channel.is_active {
                                                span { class: "badge", style: "background:var(--success);color:#fff", "active" }
                                            } else {
                                                span { class: "badge", "retired" }
                                            }
                                            button {
                                                class: "ghost",
                                                r#type: "button",
                                                disabled: pending(),
                                                onclick: move |_| toggle_channel(row.clone()),
                                                if channel.is_active { "Retire" } else { "Reactivate" }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    },
                    Some(Err(message)) => rsx! { p { class: "state error", "Could not load channels: {message}" } },
                    _ => rsx! { p { class: "state", "Loading channels…" } },
                }
                form { style: "margin-top:.8rem;border-top:1px solid var(--border);padding-top:.8rem", onsubmit: save_channel,
                    div { class: "field-grid",
                        div { class: "field",
                            label { r#for: "channel-key", "Key" }
                            input {
                                id: "channel-key",
                                r#type: "text",
                                value: "{channel_key}",
                                oninput: move |e| channel_key.set(e.value()),
                            }
                        }
                        div { class: "field",
                            label { r#for: "channel-name", "Name" }
                            input {
                                id: "channel-name",
                                r#type: "text",
                                value: "{channel_name}",
                                oninput: move |e| channel_name.set(e.value()),
                            }
                        }
                    }
                    div { class: "field", style: "margin-bottom:.6rem",
                        label { r#for: "channel-kind", "Kind" }
                        select {
                            id: "channel-kind",
                            value: "{channel_kind}",
                            oninput: move |e| channel_kind.set(e.value()),
                            for kind in CHANNEL_KINDS {
                                option { key: "{kind}", value: "{kind}", "{status_label(kind)}" }
                            }
                        }
                    }
                    div { class: "field", style: "margin-bottom:.6rem",
                        label { r#for: "channel-webhook", "Delivery webhook (optional)" }
                        input {
                            id: "channel-webhook",
                            r#type: "url",
                            placeholder: "https://partner.example.com/hooks/meridian",
                            value: "{channel_webhook}",
                            oninput: move |e| channel_webhook.set(e.value()),
                        }
                    }
                    p { class: "muted", style: "font-size:.78rem",
                        "A channel with a delivery webhook is POSTed the published article on release; the receipt then records delivered/failed instead of not-delivered. Authentication secrets aren't stored here — the endpoint owner supplies how to authenticate."
                    }
                    button { class: "primary", r#type: "submit", disabled: pending(), "Save channel" }
                }
            }

            // --- feature flags ---
            div { class: "card", style: "margin-bottom:1rem;padding:1rem",
                h3 { style: "margin-top:0", "Feature flags" }
                match &*flags.read_unchecked() {
                    Some(Ok(Some(rows))) if rows.is_empty() => rsx! {
                        p { class: "state", "No feature flags defined." }
                    },
                    Some(Ok(Some(rows))) => rsx! {
                        ul { class: "rowlist",
                            for flag in rows.iter() {
                                {
                                    let toggle_key = flag.key.clone();
                                    let kill_key = flag.key.clone();
                                    let is_enabled = flag.enabled;
                                    rsx! {
                                        li { key: "{flag.key}", class: "rowitem",
                                            span { class: "grow",
                                                div { style: "font-weight:600", "{flag.key}" }
                                                if let Some(description) = &flag.description {
                                                    div { class: "muted", style: "font-size:.8rem", "{description}" }
                                                }
                                                div { class: "muted", style: "font-size:.8rem", "Rollout {flag.rollout_percent}%" }
                                            }
                                            if flag.emergency_disabled {
                                                span { class: "badge", style: "background:var(--warning)", "emergency off" }
                                            }
                                            button {
                                                class: "ghost",
                                                r#type: "button",
                                                disabled: pending(),
                                                onclick: move |_| toggle_flag(toggle_key.clone(), !is_enabled),
                                                if is_enabled { "Disable" } else { "Enable" }
                                            }
                                            if !flag.emergency_disabled {
                                                button {
                                                    class: "ghost",
                                                    r#type: "button",
                                                    disabled: pending(),
                                                    onclick: move |_| kill_flag(kill_key.clone()),
                                                    "Emergency off"
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    },
                    Some(Ok(None)) => rsx! { p { class: "state", "Sign in to see feature flags." } },
                    Some(Err(message)) => rsx! { p { class: "state error", "Could not load feature flags: {message}" } },
                    None => rsx! { p { class: "state", "Loading feature flags…" } },
                }
            }
        }
    }
}

/// `/admin/roles` — the capability × role matrix and the effective-permission
/// viewer.
///
/// `admin.rs` was fully built — escalation guards, simulate, effective
/// permissions — with no UI at all. Two things are surfaced here:
///
/// 1. **The matrix.** Every registered capability against every role, split by the
///    Phase 0 `scope` so the org-wide tier and the per-workspace tier read as the
///    two different things they are. The twelve built-in roles are `is_system` and
///    projected from the code registry by `sync_system_roles`, so the grid is a
///    faithful read rather than an editor pretending to write.
/// 2. **The viewer.** Resolve every capability for one person, optionally inside
///    one sector, showing which rule in the chain decided each — the answer to
///    "why can they publish in Politics?".
#[component]
fn RolesAdmin() -> Element {
    let session = use_context::<Signal<Option<Session>>>();
    let scope = use_context::<Signal<SectorScope>>();
    let sectors = scope.read().sectors.clone();

    let capabilities = use_resource(move || async move {
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::capabilities(s.access_token).await.map(Some),
        }
    });
    let roles = use_resource(move || async move {
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::roles(s.access_token).await.map(Some),
        }
    });
    let people = use_resource(move || async move {
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::users(s.access_token).await.map(Some),
        }
    });

    let mut subject = use_signal(String::new);
    let mut desk = use_signal(String::new);

    let decisions = use_resource(move || {
        let who = subject();
        let where_ = desk();
        async move {
            if who.is_empty() {
                return Ok(None);
            }
            let sector = (!where_.is_empty()).then_some(where_);
            match session.read().clone() {
                None => Ok(None),
                Some(s) => api::effective_permissions(s.access_token, who, sector).await.map(Some),
            }
        }
    });

    rsx! {
        Guard { title: "Roles & Permissions",
            div { class: "page-head",
                div {
                    p { class: "eyebrow", "Governance" }
                    h1 { class: "page-title", "Roles & Permissions" }
                    p { class: "page-sub",
                        "Deny-by-default. An unregistered capability is granted to nobody."
                    }
                }
                div { class: "head-actions",
                    Link { to: Route::SectorAdmin {}, class: "ghost", "Sector registry" }
                }
            }

            // --- the effective-permission viewer ---
            div { class: "card", style: "margin-bottom:1.25rem;padding:1rem",
                h3 { style: "margin-top:0", "Why can this person do that?" }
                div { style: "display:flex;gap:.6rem;flex-wrap:wrap;margin-bottom:.6rem",
                    div { class: "field",
                        label { r#for: "eff-user", "Person" }
                        select {
                            id: "eff-user",
                            value: "{subject}",
                            oninput: move |e| subject.set(e.value()),
                            option { value: "", "Select a person…" }
                            if let Some(Ok(Some(rows))) = &*people.read_unchecked() {
                                for person in rows.iter() {
                                    option { key: "{person.id}", value: "{person.id}",
                                        "{person.display_name} ({person.role})"
                                    }
                                }
                            }
                        }
                    }
                    div { class: "field",
                        label { r#for: "eff-desk", "Sector" }
                        select {
                            id: "eff-desk",
                            value: "{desk}",
                            oninput: move |e| desk.set(e.value()),
                            option { value: "", "Org level (no sector)" }
                            for sector in sectors.iter() {
                                option { key: "{sector.id}", value: "{sector.id}", "{sector.name}" }
                            }
                        }
                    }
                }
                match &*decisions.read_unchecked() {
                    Some(Ok(Some(result))) => rsx! {
                        table { class: "table",
                            thead { tr { th { "Capability" } th { "Outcome" } th { "Decided by" } } }
                            tbody {
                                for decision in result.permissions.iter() {
                                    tr { key: "{decision.capability}",
                                        td { style: "font-family:var(--font-mono);font-size:.85rem", "{decision.capability}" }
                                        td {
                                            span {
                                                class: "badge",
                                                style: if decision.allowed {
                                                    "background:var(--success);color:#fff"
                                                } else {
                                                    "background:var(--muted)"
                                                },
                                                if decision.allowed { "allow" } else { "deny" }
                                            }
                                        }
                                        td { class: "muted", style: "font-size:.85rem", "{decision.source}" }
                                    }
                                }
                            }
                        }
                    },
                    Some(Ok(None)) => rsx! {
                        p { class: "muted", style: "font-size:.85rem",
                            "Pick a person to resolve every capability for them."
                        }
                    },
                    Some(Err(message)) => rsx! { p { class: "state error", "{message}" } },
                    None => rsx! { p { class: "state", "Resolving…" } },
                }
            }

            // --- the capability × role matrix ---
            h3 { "Capability matrix" }
            match (&*capabilities.read_unchecked(), &*roles.read_unchecked()) {
                (Some(Ok(Some(caps))), Some(Ok(Some(role_rows)))) => rsx! {
                    for tier in ["global", "sector"] {
                        {
                            let tier_caps: Vec<&api::CapabilityRow> = caps
                                .iter()
                                .filter(|c| c.scope.as_deref().unwrap_or("sector") == tier)
                                .collect();
                            let tier_roles: Vec<&api::RoleRow> = role_rows
                                .iter()
                                .filter(|r| {
                                    let is_global = matches!(
                                        r.key.as_str(),
                                        "admin" | "editor_in_chief" | "standards_legal" | "audience_editor"
                                    );
                                    if tier == "global" { is_global } else { !is_global }
                                })
                                .collect();
                            rsx! {
                                div { key: "{tier}", style: "margin-bottom:1.5rem",
                                    div { class: "mini-label",
                                        if tier == "global" {
                                            "Org-wide — carried everywhere, overlaying every sector"
                                        } else {
                                            "Per workspace — held through a sector membership"
                                        }
                                    }
                                    div { style: "overflow-x:auto",
                                        table { class: "table",
                                            thead {
                                                tr {
                                                    th { "Capability" }
                                                    for role in tier_roles.iter() {
                                                        th { key: "{role.key}", style: "font-size:.75rem", "{role.name}" }
                                                    }
                                                }
                                            }
                                            tbody {
                                                for capability in tier_caps.iter() {
                                                    tr { key: "{capability.key}",
                                                        td {
                                                            div { style: "font-weight:600;font-size:.85rem", "{capability.label}" }
                                                            div {
                                                                class: "muted",
                                                                style: "font-family:var(--font-mono);font-size:.75rem",
                                                                "{capability.key}"
                                                            }
                                                        }
                                                        for role in tier_roles.iter() {
                                                            td {
                                                                key: "{role.key}",
                                                                style: "text-align:center",
                                                                if role.capabilities.iter().any(|c| c == &capability.key) {
                                                                    span { style: "color:var(--success);font-weight:700", "●" }
                                                                } else {
                                                                    span { class: "muted", "–" }
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    p { class: "muted", style: "font-size:.8rem",
                        "The twelve built-in roles are system roles projected from the code registry at startup, so this grid is read-only. Custom roles and per-user or per-desk policy overrides are the editable layer."
                    }
                },
                (Some(Err(message)), _) | (_, Some(Err(message))) => rsx! {
                    p { class: "state error", "Could not load the matrix: {message}" }
                },
                (Some(Ok(None)), _) | (_, Some(Ok(None))) => rsx! {
                    p { class: "state", "Sign in to see the matrix." }
                },
                _ => rsx! { p { class: "state", "Loading the capability matrix…" } },
            }

            CustomRoles {}
        }
    }
}

/// Create, re-scope and delete **custom** roles — the editable layer the read-only
/// matrix above points to. Built-in roles are projected from the code registry and
/// the backend refuses to mutate them (`update_role`/`delete_role` 409 on
/// `is_system`), so only custom roles appear here; the capability set the actor may
/// grant is itself bounded server-side by the "can package" check, so this form
/// can't be used to escalate beyond what the actor already holds.
#[component]
fn CustomRoles() -> Element {
    let session = use_context::<Signal<Option<Session>>>();
    let mut reload = use_signal(|| 0_u32);
    let mut status = use_signal(|| None::<String>);
    let mut editing = use_signal(|| None::<String>);
    let mut f_key = use_signal(String::new);
    let mut f_name = use_signal(String::new);
    let mut f_desc = use_signal(String::new);
    let mut f_caps = use_signal(Vec::<String>::new);
    let mut busy = use_signal(|| false);

    let roles = use_resource(move || async move {
        reload();
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::roles(s.access_token).await.map(Some),
        }
    });
    let capabilities = use_resource(move || async move {
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::capabilities(s.access_token).await.map(Some),
        }
    });

    let custom: Vec<api::RoleRow> = match &*roles.read_unchecked() {
        Some(Ok(Some(rows))) => rows.iter().filter(|r| !r.is_system).cloned().collect(),
        _ => Vec::new(),
    };
    let caps: Vec<api::CapabilityRow> = match &*capabilities.read_unchecked() {
        Some(Ok(Some(rows))) => rows.clone(),
        _ => Vec::new(),
    };

    let selected = f_caps.read().clone();
    let is_editing = editing().is_some();
    let dirty = is_editing || !f_key().is_empty() || !f_name().is_empty();

    let save = move |_| {
        if busy() {
            return;
        }
        let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
            return;
        };
        let key = f_key().trim().to_owned();
        let name = f_name().trim().to_owned();
        let desc = f_desc().trim().to_owned();
        let caps_now = f_caps();
        if name.is_empty() {
            status.set(Some("Name is required.".to_owned()));
            return;
        }
        let editing_key = editing();
        if editing_key.is_none() && key.is_empty() {
            status.set(Some("A key is required for a new role.".to_owned()));
            return;
        }
        busy.set(true);
        status.set(None);
        spawn(async move {
            let description = (!desc.is_empty()).then_some(desc);
            let result = match editing_key {
                Some(k) => api::update_role(token, k, Some(name), description, caps_now).await,
                None => api::create_role(token, key, name, description, caps_now).await,
            };
            match result {
                Ok(()) => {
                    status.set(Some("Saved.".to_owned()));
                    editing.set(None);
                    f_key.set(String::new());
                    f_name.set(String::new());
                    f_desc.set(String::new());
                    f_caps.set(Vec::new());
                    reload += 1;
                }
                Err(m) => status.set(Some(m)),
            }
            busy.set(false);
        });
    };

    rsx! {
        div { class: "card", style: "margin-top:1.5rem;padding:1rem",
            div { class: "spread",
                h3 { style: "margin:0", "Custom roles" }
                if dirty {
                    button {
                        class: "ghost",
                        r#type: "button",
                        style: "font-size:.8rem",
                        onclick: move |_| {
                            editing.set(None);
                            f_key.set(String::new());
                            f_name.set(String::new());
                            f_desc.set(String::new());
                            f_caps.set(Vec::new());
                            status.set(None);
                        },
                        "Cancel"
                    }
                }
            }
            p { class: "muted", style: "font-size:.82rem",
                "Built-in roles are defined in code and can't be changed here. Create a role, choose the capabilities it grants, then assign it above. You can only grant capabilities you're able to package."
            }
            if let Some(message) = status() {
                p { class: "state", style: "margin:.4rem 0", role: "status", "{message}" }
            }

            if custom.is_empty() {
                p { class: "muted", style: "font-size:.85rem", "No custom roles yet." }
            } else {
                ul { class: "rowlist",
                    for role in custom.iter() {
                        li { key: "{role.key}", class: "rowitem",
                            div { class: "grow",
                                div { style: "font-weight:650", "{role.name}" }
                                div { class: "muted", style: "font-family:var(--font-mono);font-size:.75rem",
                                    "{role.key} · {role.capabilities.len()} capabilities"
                                }
                            }
                            {
                                let r = role.clone();
                                rsx! {
                                    button {
                                        class: "ghost",
                                        r#type: "button",
                                        style: "font-size:.8rem",
                                        onclick: move |_| {
                                            editing.set(Some(r.key.clone()));
                                            f_key.set(r.key.clone());
                                            f_name.set(r.name.clone());
                                            f_desc.set(r.description.clone().unwrap_or_default());
                                            f_caps.set(r.capabilities.clone());
                                            status.set(None);
                                        },
                                        "Edit"
                                    }
                                }
                            }
                            {
                                let del_key = role.key.clone();
                                rsx! {
                                    button {
                                        class: "ghost",
                                        r#type: "button",
                                        style: "font-size:.8rem",
                                        title: "Delete role",
                                        onclick: move |_| {
                                            let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else { return; };
                                            let key = del_key.clone();
                                            spawn(async move {
                                                match api::delete_role(token, key).await {
                                                    Ok(()) => { status.set(Some("Role deleted.".to_owned())); reload += 1; }
                                                    Err(m) => status.set(Some(m)),
                                                }
                                            });
                                        },
                                        "✕"
                                    }
                                }
                            }
                        }
                    }
                }
            }

            div { style: "margin-top:1rem;border-top:1px solid var(--border);padding-top:1rem",
                div { class: "mini-label", if is_editing { "Edit role" } else { "New role" } }
                div { style: "display:flex;gap:.6rem;flex-wrap:wrap",
                    div { class: "field",
                        label { r#for: "role-key", "Key" }
                        input {
                            id: "role-key",
                            value: "{f_key}",
                            disabled: is_editing,
                            placeholder: "e.g. weekend_editor",
                            oninput: move |e| f_key.set(e.value()),
                        }
                    }
                    div { class: "field",
                        label { r#for: "role-name", "Name" }
                        input {
                            id: "role-name",
                            value: "{f_name}",
                            placeholder: "Weekend Editor",
                            oninput: move |e| f_name.set(e.value()),
                        }
                    }
                    div { class: "field", style: "flex:1;min-width:14rem",
                        label { r#for: "role-desc", "Description" }
                        input {
                            id: "role-desc",
                            value: "{f_desc}",
                            oninput: move |e| f_desc.set(e.value()),
                        }
                    }
                }

                div { class: "mini-label", style: "margin-top:.8rem", "Capabilities granted" }
                for tier in ["global", "sector"] {
                    {
                        let tier_caps: Vec<&api::CapabilityRow> = caps
                            .iter()
                            .filter(|c| c.scope.as_deref().unwrap_or("sector") == tier)
                            .collect();
                        rsx! {
                            if !tier_caps.is_empty() {
                                div { key: "{tier}", style: "margin:.35rem 0",
                                    div { class: "muted", style: "font-size:.72rem;text-transform:uppercase;letter-spacing:.04em",
                                        if tier == "global" { "Org-wide" } else { "Per workspace" }
                                    }
                                    div { style: "display:flex;flex-wrap:wrap;gap:.35rem .9rem;margin-top:.3rem",
                                        for cap in tier_caps.iter() {
                                            {
                                                let ckey = cap.key.clone();
                                                let checked = selected.iter().any(|c| c == &cap.key);
                                                rsx! {
                                                    label { key: "{cap.key}",
                                                        style: "display:flex;align-items:center;gap:.35rem;font-size:.8rem",
                                                        input {
                                                            r#type: "checkbox",
                                                            checked,
                                                            onchange: move |_| {
                                                                let mut set = f_caps.write();
                                                                if let Some(pos) = set.iter().position(|c| c == &ckey) {
                                                                    set.remove(pos);
                                                                } else {
                                                                    set.push(ckey.clone());
                                                                }
                                                            },
                                                        }
                                                        span { title: "{cap.key}", "{cap.label}" }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                button {
                    class: "primary",
                    r#type: "button",
                    style: "margin-top:.9rem",
                    disabled: busy(),
                    onclick: save,
                    if is_editing { "Save changes" } else { "Create role" }
                }
            }
        }
    }
}

/// `/org/search` — permission-filtered story search.
///
/// The topbar previously rendered a static search box with no handler. Results are
/// whatever the backend's `search_stories` returns, so they are already narrowed to
/// what the viewer may see. Note the index covers title, dek and category only —
/// the block body is not yet decomposed, which is why a body-only match will miss.
#[component]
fn SearchResults() -> Element {
    let session = use_context::<Signal<Option<Session>>>();
    let scope = use_context::<Signal<SectorScope>>();
    let mut query = use_signal(String::new);
    let mut submitted = use_signal(String::new);
    // Every filter is now applied server-side; the facet counts come back with the
    // results and reflect the current query, so the buttons genuinely narrow.
    let mut state_filter = use_signal(String::new);
    let mut category_filter = use_signal(String::new);
    let mut desk_filter = use_signal(String::new);
    let mut since = use_signal(String::new);
    let mut until = use_signal(String::new);
    let mut offset = use_signal(|| 0_i64);
    let mut filters_open = use_signal(|| false);
    // Which corpus to search: "stories" (full filters), "coverage" or "corrections".
    let mut kind = use_signal(|| "stories".to_owned());

    const PAGE_SIZE: i64 = 25;

    let page = use_resource(move || {
        let term = submitted();
        let (st, cat, dk) = (state_filter(), category_filter(), desk_filter());
        let (from, to, off, k) = (since(), until(), offset(), kind());
        async move {
            // Story corpus only; and nothing to ask for with no query and no filters.
            if k != "stories" {
                return Ok(None);
            }
            if term.trim().is_empty() && st.is_empty() && cat.is_empty() && dk.is_empty() && from.is_empty() && to.is_empty() {
                return Ok(None);
            }
            match session.read().clone() {
                None => Ok(None),
                Some(s) => api::search_full(s.access_token, term, st, cat, dk, from, to, PAGE_SIZE, off).await.map(Some),
            }
        }
    });

    // Coverage / corrections corpus (substring, desk + date, paginated).
    let corpus = use_resource(move || {
        let k = kind();
        let term = submitted();
        let (dk, from, to, off) = (desk_filter(), since(), until(), offset());
        async move {
            if k == "stories" {
                return Ok(None);
            }
            if term.trim().is_empty() && dk.is_empty() && from.is_empty() && to.is_empty() {
                return Ok(None);
            }
            match session.read().clone() {
                None => Ok(None),
                Some(s) => api::search_corpus(s.access_token, k, term, dk, from, to, PAGE_SIZE, off).await.map(Some),
            }
        }
    });

    // Desks for the desk filter (the viewer's own memberships).
    let desks = use_resource(move || async move {
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::my_sectors(s.access_token).await.map(Some),
        }
    });
    let desk_list: Vec<(String, String)> = match &*desks.read_unchecked() {
        Some(Ok(Some(list))) => list.iter().map(|d| (d.id.clone(), d.name.clone())).collect(),
        _ => Vec::new(),
    };
    let desk_name = |id: &str| -> String {
        desk_list.iter().find(|(did, _)| did == id).map(|(_, n)| n.clone()).unwrap_or_else(|| "Desk".to_owned())
    };

    let mut reload_saved = use_signal(|| 0_u32);
    let mut save_error = use_signal(|| None::<String>);
    let mut saving = use_signal(|| false);
    let mut save_name = use_signal(String::new);
    let mut save_shared = use_signal(|| false);
    let mut naming = use_signal(|| false);

    let saved = use_resource(move || async move {
        reload_saved();
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::saved_searches(s.access_token).await.map(Some),
        }
    });

    let save_current = move |event: FormEvent| {
        event.prevent_default();
        if saving() {
            return;
        }
        let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
            return;
        };
        let name = save_name();
        if name.trim().is_empty() {
            save_error.set(Some("Give the search a name.".to_owned()));
            return;
        }
        let term = submitted();
        if term.trim().is_empty() {
            save_error.set(Some("Run a search first — there is nothing to save yet.".to_owned()));
            return;
        }
        // `saved_searches` has no unique constraint on (user_id, name) — verified
        // against the live schema, where a duplicate insert succeeds — so two
        // searches with the same name would be indistinguishable in the list
        // below. Guard here rather than letting that happen silently.
        let clash = match &*saved.read_unchecked() {
            Some(Ok(Some(rows))) => rows.iter().any(|row| row.name.eq_ignore_ascii_case(name.trim())),
            _ => false,
        };
        if clash {
            save_error.set(Some("You already have a saved search with that name.".to_owned()));
            return;
        }
        let (state, category, shared) = (state_filter(), category_filter(), save_shared());
        saving.set(true);
        save_error.set(None);
        spawn(async move {
            match api::create_saved_search(token, name, term, state, category, shared).await {
                Ok(()) => {
                    save_name.set(String::new());
                    naming.set(false);
                    reload_saved += 1;
                }
                Err(message) => save_error.set(Some(message)),
            }
            saving.set(false);
        });
    };

    let mut drop_saved = move |search_id: String| {
        if saving() {
            return;
        }
        let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
            return;
        };
        saving.set(true);
        save_error.set(None);
        spawn(async move {
            match api::delete_saved_search(token, search_id).await {
                Ok(()) => reload_saved += 1,
                Err(message) => save_error.set(Some(message)),
            }
            saving.set(false);
        });
    };

    rsx! {
        Guard { title: "Search",
            div { class: "page-head",
                div {
                    p { class: "eyebrow", "Organisation" }
                    h1 { class: "page-title", "Search" }
                    p { class: "page-sub",
                        "Titles, deks and categories across every sector you can see."
                    }
                }
            }
            form {
                class: "card",
                style: "margin-bottom:1rem;padding:1rem;display:flex;gap:.6rem",
                onsubmit: move |event: FormEvent| {
                    event.prevent_default();
                    offset.set(0);
                    submitted.set(query());
                },
                input {
                    style: "flex:1",
                    r#type: "search",
                    value: "{query}",
                    oninput: move |e| query.set(e.value()),
                    "aria-label": "Search stories",
                }
                button { class: "primary", r#type: "submit", "Search" }
            }

            // --- corpus switch: which kind of record to search ---
            div { class: "segmented", style: "margin-bottom:1rem",
                for (val , label) in [("stories", "Stories"), ("coverage", "Coverage"), ("corrections", "Corrections")] {
                    button {
                        key: "{val}",
                        class: if kind() == val { "seg-btn active" } else { "seg-btn" },
                        r#type: "button",
                        onclick: move |_| {
                            kind.set(val.to_owned());
                            offset.set(0);
                            // Story-only facets don't apply to the other corpora.
                            if val != "stories" { state_filter.set(String::new()); category_filter.set(String::new()); }
                        },
                        "{label}"
                    }
                }
            }

            // --- saved searches ---
            div { class: "card", style: "margin-bottom:1rem;padding:1rem",
                div { class: "spread",
                    h3 { style: "margin:0", "Saved searches" }
                    button {
                        class: "linklike",
                        r#type: "button",
                        onclick: move |_| {
                            let open = naming();
                            naming.set(!open);
                            save_error.set(None);
                        },
                        if naming() { "Cancel" } else { "Save this search" }
                    }
                }
                if let Some(message) = save_error() {
                    p { class: "state error", role: "alert", "{message}" }
                }
                match &*saved.read_unchecked() {
                    Some(Ok(Some(rows))) if rows.is_empty() => rsx! {
                        p { class: "muted", style: "font-size:.85rem", "Nothing saved yet." }
                    },
                    Some(Ok(Some(rows))) => rsx! {
                        ul { class: "rowlist",
                            for entry in rows.iter() {
                                {
                                    let search_id = entry.id.clone();
                                    let restore_query = entry.query.clone();
                                    let restore_state = entry.filter("workflow_state");
                                    let restore_category = entry.filter("category");
                                    rsx! {
                                        li { key: "{entry.id}", class: "rowitem",
                                            button {
                                                class: "linklike grow",
                                                style: "text-align:left",
                                                r#type: "button",
                                                onclick: move |_| {
                                                    // Restore the whole search, not just the
                                                    // words: the facets were part of what was
                                                    // being looked at.
                                                    query.set(restore_query.clone());
                                                    submitted.set(restore_query.clone());
                                                    state_filter.set(restore_state.clone());
                                                    category_filter.set(restore_category.clone());
                                                },
                                                div { style: "font-weight:600", "{entry.name}" }
                                                div { class: "muted", style: "font-size:.8rem", "“{entry.query}”" }
                                            }
                                            if entry.is_shared {
                                                span { class: "badge", "shared" }
                                            }
                                            button {
                                                class: "ghost",
                                                r#type: "button",
                                                disabled: saving(),
                                                onclick: move |_| drop_saved(search_id.clone()),
                                                "Delete"
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    },
                    Some(Ok(None)) => rsx! { p { class: "state", "Sign in to see saved searches." } },
                    Some(Err(message)) => rsx! { p { class: "state error", "Could not load saved searches: {message}" } },
                    None => rsx! { p { class: "state", "Loading saved searches…" } },
                }
                if naming() {
                    form { style: "margin-top:.8rem;border-top:1px solid var(--border);padding-top:.8rem", onsubmit: save_current,
                        div { class: "field", style: "margin-bottom:.6rem",
                            label { r#for: "saved-name", "Name" }
                            input {
                                id: "saved-name",
                                r#type: "text",
                                value: "{save_name}",
                                oninput: move |e| save_name.set(e.value()),
                            }
                        }
                        label { style: "display:flex;align-items:center;gap:.4rem;margin-bottom:.6rem",
                            input {
                                r#type: "checkbox",
                                checked: save_shared(),
                                onchange: move |e| save_shared.set(e.checked()),
                            }
                            "Share with the newsroom"
                        }
                        p { class: "muted", style: "font-size:.78rem",
                            "Saves the query and the facets currently in force. Results are never stored, so a saved search cannot go stale."
                        }
                        button { class: "primary", r#type: "submit", disabled: saving(), "Save" }
                    }
                }
            }

            // --- filters (bottom sheet on mobile / modal on desktop) ---
            div { class: "search-filterbar",
                button { class: "filters-btn", r#type: "button", onclick: move |_| filters_open.set(true),
                    Icon { name: "settings" }
                    "Filters"
                    {
                        let active = u8::from(!state_filter().is_empty()) + u8::from(!category_filter().is_empty())
                            + u8::from(!desk_filter().is_empty()) + u8::from(!since().is_empty()) + u8::from(!until().is_empty());
                        rsx! { if active > 0 { span { class: "filters-count", "{active}" } } }
                    }
                }
                if !state_filter().is_empty() {
                    button { class: "filter-chip", r#type: "button", onclick: move |_| { state_filter.set(String::new()); offset.set(0); },
                        "{status_label(&state_filter())}" span { class: "filter-chip-x", "\u{2715}" } }
                }
                if !category_filter().is_empty() {
                    button { class: "filter-chip", r#type: "button", onclick: move |_| { category_filter.set(String::new()); offset.set(0); },
                        "{category_filter()}" span { class: "filter-chip-x", "\u{2715}" } }
                }
                if !desk_filter().is_empty() {
                    button { class: "filter-chip", r#type: "button", onclick: move |_| { desk_filter.set(String::new()); offset.set(0); },
                        "{desk_name(&desk_filter())}" span { class: "filter-chip-x", "\u{2715}" } }
                }
                if !since().is_empty() || !until().is_empty() {
                    button { class: "filter-chip", r#type: "button", onclick: move |_| { since.set(String::new()); until.set(String::new()); offset.set(0); },
                        {
                            let label = match (since().is_empty(), until().is_empty()) {
                                (false, false) => format!("{} → {}", since(), until()),
                                (false, true) => format!("from {}", since()),
                                (true, false) => format!("until {}", until()),
                                (true, true) => String::new(),
                            };
                            rsx! { "{label}" span { class: "filter-chip-x", "\u{2715}" } }
                        }
                    }
                }
            }
            if filters_open() {
                div { class: "sheet-backdrop", onclick: move |_| filters_open.set(false),
                    div { class: "sheet", onclick: move |e| e.stop_propagation(),
                        header { class: "sheet-head",
                            h3 { "Filter results" }
                            button { class: "sheet-x", r#type: "button", aria_label: "Close", onclick: move |_| filters_open.set(false), "\u{2715}" }
                        }
                        div { class: "sheet-body",
                            // Stage + Category facets are story-only; they come from
                            // the current result set so the counts track the query.
                            if kind() == "stories" {
                                if let Some(Ok(Some(pg))) = &*page.read_unchecked() {
                                div { class: "mini-label", style: "margin-top:0", "Stage" }
                                div { class: "seg-wrap",
                                    button { class: if state_filter().is_empty() { "seg-btn active" } else { "seg-btn" }, r#type: "button", onclick: move |_| { state_filter.set(String::new()); offset.set(0); }, "Any" }
                                    for (state , count) in pg.facets.workflow_state.iter() {
                                        {
                                            let value = state.clone();
                                            rsx! {
                                                button { key: "{state}", class: if state_filter() == *state { "seg-btn active" } else { "seg-btn" }, r#type: "button", onclick: move |_| { state_filter.set(value.clone()); offset.set(0); }, "{status_label(state)} ({count})" }
                                            }
                                        }
                                    }
                                }
                                div { class: "mini-label", "Category" }
                                div { class: "seg-wrap",
                                    button { class: if category_filter().is_empty() { "seg-btn active" } else { "seg-btn" }, r#type: "button", onclick: move |_| { category_filter.set(String::new()); offset.set(0); }, "Any" }
                                    for (category , count) in pg.facets.category.iter() {
                                        {
                                            let value = category.clone();
                                            rsx! {
                                                button { key: "{category}", class: if category_filter() == *category { "seg-btn active" } else { "seg-btn" }, r#type: "button", onclick: move |_| { category_filter.set(value.clone()); offset.set(0); }, "{category} ({count})" }
                                            }
                                        }
                                    }
                                }
                                } else {
                                    p { class: "muted", style: "font-size:.78rem;margin-top:0", "Run a search to see stage and category counts." }
                                }
                            }
                            // Desk applies to stories + coverage; date applies to all.
                            if !desk_list.is_empty() && kind() != "corrections" {
                                div { class: "mini-label", "Desk" }
                                div { class: "seg-wrap",
                                    button { class: if desk_filter().is_empty() { "seg-btn active" } else { "seg-btn" }, r#type: "button", onclick: move |_| { desk_filter.set(String::new()); offset.set(0); }, "Any" }
                                    for (id , name) in desk_list.iter() {
                                        {
                                            let value = id.clone();
                                            rsx! {
                                                button { key: "{id}", class: if desk_filter() == *id { "seg-btn active" } else { "seg-btn" }, r#type: "button", onclick: move |_| { desk_filter.set(value.clone()); offset.set(0); }, "{name}" }
                                            }
                                        }
                                    }
                                }
                            }
                            div { class: "mini-label", "Updated between" }
                            div { style: "display:flex;gap:.6rem;flex-wrap:wrap",
                                input { r#type: "date", class: "input", value: "{since()}", "aria-label": "Updated from", oninput: move |e| { since.set(e.value()); offset.set(0); } }
                                span { class: "muted", style: "align-self:center", "→" }
                                input { r#type: "date", class: "input", value: "{until()}", "aria-label": "Updated until", oninput: move |e| { until.set(e.value()); offset.set(0); } }
                            }
                        }
                        footer { class: "sheet-foot",
                            button { class: "ei-ghost", r#type: "button", onclick: move |_| { state_filter.set(String::new()); category_filter.set(String::new()); desk_filter.set(String::new()); since.set(String::new()); until.set(String::new()); offset.set(0); }, "Clear all" }
                            button { class: "ei-cta", r#type: "button", onclick: move |_| filters_open.set(false), "Show results" }
                        }
                    }
                }
            }
            if kind() == "stories" {
                match &*page.read_unchecked() {
                    Some(Ok(Some(pg))) if pg.results.is_empty() => rsx! {
                        p { class: "state", "No stories match this search." }
                    },
                    Some(Ok(Some(pg))) => {
                        let total = pg.total;
                        let off = pg.offset;
                        let count = pg.results.len() as i64;
                        let start = if count == 0 { 0 } else { off + 1 };
                        let end = off + count;
                        let has_more = pg.has_more;
                        let can_prev = off > 0;
                        rsx! {
                            div { class: "pubq-toolbar", style: "margin:.2rem 0 .8rem",
                                span { class: "muted", style: "font-size:.82rem", "Showing {start}\u{2013}{end} of {total}" }
                            }
                            div { class: "pubq-wrap",
                                table { class: "table pubq",
                                    thead { tr {
                                        th { "Headline" }
                                        th { "Category" }
                                        th { "Stage" }
                                        th { "Updated" }
                                    } }
                                    tbody {
                                        for hit in pg.results.iter() {
                                            tr { key: "{hit.id}",
                                                td { "data-label": "Headline",
                                                    Link {
                                                        to: Route::StoryEditor { id: hit.id.clone() },
                                                        style: "font-weight:650",
                                                        "{hit.title}"
                                                    }
                                                    if !hit.dek.is_empty() {
                                                        div { class: "muted", style: "font-size:.8rem", "{hit.dek}" }
                                                    }
                                                }
                                                td { class: "muted", "data-label": "Category", "{hit.category}" }
                                                td { "data-label": "Stage", span { class: "badge status-{hit.workflow_state}", "{status_label(&hit.workflow_state)}" } }
                                                td { class: "muted", "data-label": "Updated", style: "font-size:.8rem", "{fmt_when_local(&hit.updated_at)}" }
                                            }
                                        }
                                    }
                                }
                            }
                            if can_prev || has_more {
                                div { class: "pubq-actions", style: "justify-content:center;margin-top:.9rem",
                                    button { class: "btn-sm", r#type: "button", disabled: !can_prev, onclick: move |_| { let o = offset(); offset.set((o - PAGE_SIZE).max(0)); }, "\u{2039} Previous" }
                                    button { class: "btn-sm", r#type: "button", disabled: !has_more, onclick: move |_| { let o = offset(); offset.set(o + PAGE_SIZE); }, "Next \u{203a}" }
                                }
                            }
                        }
                    },
                    Some(Ok(None)) => rsx! { p { class: "state", "Enter a term, or open Filters to browse by desk, stage or date." } },
                    Some(Err(message)) => rsx! { p { class: "state error", "Search failed: {message}" } },
                    None => rsx! { p { class: "state", "Searching…" } },
                }
            } else {
                match &*corpus.read_unchecked() {
                    Some(Ok(Some(pg))) if pg.results.is_empty() => rsx! {
                        p { class: "state", "No {kind()} match this search." }
                    },
                    Some(Ok(Some(pg))) => {
                        let total = pg.total;
                        let off = pg.offset;
                        let count = pg.results.len() as i64;
                        let start = if count == 0 { 0 } else { off + 1 };
                        let end = off + count;
                        let has_more = pg.has_more;
                        let can_prev = off > 0;
                        rsx! {
                            div { class: "pubq-toolbar", style: "margin:.2rem 0 .8rem",
                                span { class: "muted", style: "font-size:.82rem", "Showing {start}\u{2013}{end} of {total}" }
                            }
                            div { class: "pubq-wrap",
                                table { class: "table pubq",
                                    thead { tr {
                                        th { "Title" }
                                        th { "Detail" }
                                        th { "Status" }
                                        th { "Updated" }
                                    } }
                                    tbody {
                                        for hit in pg.results.iter() {
                                            {
                                                let to = if hit.kind == "correction" {
                                                    Route::CorrectionsLedger {}
                                                } else {
                                                    planning_route(&scope.read())
                                                };
                                                rsx! {
                                                    tr { key: "{hit.id}",
                                                        td { "data-label": "Title",
                                                            Link { to, style: "font-weight:650", "{hit.title}" }
                                                        }
                                                        td { class: "muted", "data-label": "Detail", style: "font-size:.82rem", "{hit.subtitle}" }
                                                        td { "data-label": "Status", span { class: "badge", "{hit.meta}" } }
                                                        td { class: "muted", "data-label": "Updated", style: "font-size:.8rem", "{fmt_when_local(&hit.updated_at)}" }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            if can_prev || has_more {
                                div { class: "pubq-actions", style: "justify-content:center;margin-top:.9rem",
                                    button { class: "btn-sm", r#type: "button", disabled: !can_prev, onclick: move |_| { let o = offset(); offset.set((o - PAGE_SIZE).max(0)); }, "\u{2039} Previous" }
                                    button { class: "btn-sm", r#type: "button", disabled: !has_more, onclick: move |_| { let o = offset(); offset.set(o + PAGE_SIZE); }, "Next \u{203a}" }
                                }
                            }
                        }
                    },
                    Some(Ok(None)) => rsx! { p { class: "state", "Enter a term, or open Filters to browse {kind()} by date." } },
                    Some(Err(message)) => rsx! { p { class: "state error", "Search failed: {message}" } },
                    None => rsx! { p { class: "state", "Searching…" } },
                }
            }
        }
    }
}

/// The drill-down keys `dashboard.rs` implements, each with a plain label. Only
/// these are offered — the backend rejects anything else with a 422, so guessing
/// would just produce errors.
const DRILLDOWN_KEYS: [(&str, &str); 6] = [
    ("pending_reviews", "Pending reviews"),
    ("overdue_tasks", "Overdue tasks"),
    ("open_corrections", "Open corrections"),
    ("failed_releases", "Failed releases"),
    ("scheduled_releases", "Scheduled releases"),
    ("stories_due_today", "Stories due today"),
];

/// The rows behind a dashboard number.
///
/// The dashboard shows counts; this answers "which ones?". Each row carries an
/// `href` the backend builds, but those are *legacy* paths (`/editor?story=…`),
/// so the link is rebuilt from `entity_type` + `entity_id` against this app's own
/// routes rather than following a path that would 404 here.
#[component]
fn Drilldowns() -> Element {
    let session = use_context::<Signal<Option<Session>>>();
    let mut key = use_signal(String::new);

    let rows = use_resource(move || {
        let picked = key();
        async move {
            if picked.is_empty() {
                return Ok(None);
            }
            match session.read().clone() {
                None => Ok(None),
                Some(s) => api::drilldown(s.access_token, picked).await.map(Some),
            }
        }
    });

    rsx! {
        div { class: "card widget", style: "margin-bottom:1.25rem",
            h3 { "🔎 What is behind the numbers" }
            div { style: "display:flex;gap:.4rem;flex-wrap:wrap;margin-bottom:.6rem",
                for (value, label) in DRILLDOWN_KEYS {
                    button {
                        key: "{value}",
                        class: if key() == value { "seg-btn active" } else { "seg-btn" },
                        r#type: "button",
                        onclick: move |_| {
                            if key() == value { key.set(String::new()); } else { key.set(value.to_owned()); }
                        },
                        "{label}"
                    }
                }
            }
            match &*rows.read_unchecked() {
                Some(Ok(Some(result))) if result.items.is_empty() => rsx! {
                    p { class: "muted", style: "font-size:.85rem", "Nothing in this category." }
                },
                Some(Ok(Some(result))) => rsx! {
                    ul { class: "rowlist",
                        for (index, item) in result.items.iter().enumerate() {
                            {
                                let entity_type = item.get("entity_type").and_then(serde_json::Value::as_str).unwrap_or("");
                                let entity_id = item.get("entity_id").and_then(serde_json::Value::as_str).unwrap_or("");
                                let title = item.get("title").and_then(serde_json::Value::as_str).unwrap_or("Untitled");
                                let subtitle = item.get("subtitle").and_then(serde_json::Value::as_str).unwrap_or("");
                                rsx! {
                                    li { key: "{index}", class: "rowitem",
                                        span { class: "grow",
                                            if entity_type == "story" {
                                                Link {
                                                    to: Route::StoryEditor { id: entity_id.to_owned() },
                                                    style: "font-weight:600",
                                                    "{title}"
                                                }
                                            } else {
                                                div { style: "font-weight:600", "{title}" }
                                            }
                                            if !subtitle.is_empty() {
                                                div { class: "muted", style: "font-size:.8rem", "{subtitle}" }
                                            }
                                        }
                                        span { class: "badge", "{entity_type}" }
                                    }
                                }
                            }
                        }
                    }
                    p { class: "muted", style: "font-size:.78rem",
                        if result.truncated {
                            "Showing the first {result.items.len()} of {result.total} — the list is capped server-side."
                        } else {
                            "{result.total} in total."
                        }
                    }
                },
                Some(Ok(None)) => rsx! {
                    p { class: "muted", style: "font-size:.85rem", "Pick a category to see the rows behind it." }
                },
                Some(Err(message)) => rsx! { p { class: "state error", "Could not load: {message}" } },
                None => rsx! { p { class: "state", "Loading…" } },
            }
        }
    }
}

/// The dashboard widgets a saved view can choose from, mirroring
/// `WIDGET_CATALOGUE` in `crates/newsroom/src/dashviews.rs`.
///
/// Every entry here must be renderable by `Dashboard`'s match below — a catalogue
/// offering something the UI cannot draw would let someone save a view that
/// silently shows nothing.
const WIDGET_CATALOGUE: [(&str, &str, bool); 7] = [
    ("summary_metrics", "Headline counts", true),
    ("attention_queue", "Attention queue", true),
    ("drilldowns", "What is behind the numbers", true),
    ("saved_views", "Saved views", true),
    ("personal_shelf", "Pinned and recently opened", true),
    ("pipeline", "Editorial pipeline", false),
    ("activity", "Recent activity", false),
];

/// Saved dashboard views: name one, share it to a sector, make one the default.
///
/// `dashviews.rs` was complete — list, create, share, set-default, duplicate,
/// delete — and unreachable.
///
/// A view stores its name, sharing scope, default flag **and its chosen widgets**:
/// the picker below writes type names from [`WIDGET_CATALOGUE`], and the server
/// turns them into grid placements so the arithmetic lives in one place. Making a
/// view the default changes what the dashboard opens with.
#[component]
fn SavedViews() -> Element {
    let session = use_context::<Signal<Option<Session>>>();
    let scope = use_context::<Signal<SectorScope>>();
    let mut reload = use_signal(|| 0_u32);
    let mut error = use_signal(|| None::<String>);
    let mut pending = use_signal(|| false);
    let mut name = use_signal(String::new);
    let mut share_to = use_signal(String::new);
    let mut adding = use_signal(|| false);
    let mut chosen = use_signal(|| {
        WIDGET_CATALOGUE
            .iter()
            .filter(|(_, _, on)| *on)
            .map(|(kind, _, _)| (*kind).to_owned())
            .collect::<Vec<String>>()
    });

    let views = use_resource(move || async move {
        reload();
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::dashboard_views(s.access_token).await.map(Some),
        }
    });

    let save = move |event: FormEvent| {
        event.prevent_default();
        if pending() {
            return;
        }
        let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
            return;
        };
        let view_name = name();
        if view_name.trim().is_empty() {
            error.set(Some("A view needs a name.".to_owned()));
            return;
        }
        let desk = share_to();
        let shared = !desk.is_empty();
        let desk = if desk.is_empty() { None } else { Some(desk) };
        let widgets = chosen();
        if widgets.is_empty() {
            error.set(Some("Choose at least one widget.".to_owned()));
            return;
        }
        pending.set(true);
        error.set(None);
        spawn(async move {
            match api::create_dashboard_view(token, view_name, None, desk, shared, widgets).await {
                Ok(()) => {
                    name.set(String::new());
                    adding.set(false);
                    reload += 1;
                }
                Err(message) => error.set(Some(message)),
            }
            pending.set(false);
        });
    };

    let mut make_default = move |view_id: String| {
        if pending() {
            return;
        }
        let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
            return;
        };
        pending.set(true);
        error.set(None);
        spawn(async move {
            match api::set_default_view(token, view_id).await {
                Ok(()) => reload += 1,
                Err(message) => error.set(Some(message)),
            }
            pending.set(false);
        });
    };

    let mut drop_view = move |view_id: String| {
        if pending() {
            return;
        }
        let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
            return;
        };
        pending.set(true);
        error.set(None);
        spawn(async move {
            match api::delete_dashboard_view(token, view_id).await {
                Ok(()) => reload += 1,
                Err(message) => error.set(Some(message)),
            }
            pending.set(false);
        });
    };

    let rows = match &*views.read_unchecked() {
        Some(Ok(Some(rows))) => rows.clone(),
        _ => Vec::new(),
    };

    rsx! {
        div { class: "card widget", style: "margin-bottom:1.25rem",
            div { class: "spread",
                h3 { "🗂 Saved views" }
                button {
                    class: "linklike",
                    r#type: "button",
                    onclick: move |_| {
                        let open = adding();
                        adding.set(!open);
                        error.set(None);
                    },
                    if adding() { "Cancel" } else { "New view" }
                }
            }
            if let Some(message) = error() {
                p { class: "state error", role: "alert", "{message}" }
            }
            if rows.is_empty() {
                p { class: "muted", style: "font-size:.85rem", "No saved views yet." }
            } else {
                ul { class: "rowlist",
                    for view in rows.iter() {
                        {
                            let default_id = view.id.clone();
                            let delete_id = view.id.clone();
                            let is_default = view.is_default;
                            rsx! {
                                li { key: "{view.id}", class: "rowitem",
                                    span { class: "grow",
                                        div { style: "font-weight:600", "{view.name}" }
                                        if let Some(description) = &view.description {
                                            div { class: "muted", style: "font-size:.8rem", "{description}" }
                                        }
                                    }
                                    if view.is_shared {
                                        span { class: "badge", "shared" }
                                    }
                                    if is_default {
                                        span { class: "badge", style: "background:var(--success);color:#fff", "default" }
                                    } else {
                                        button {
                                            class: "ghost",
                                            r#type: "button",
                                            disabled: pending(),
                                            onclick: move |_| make_default(default_id.clone()),
                                            "Make default"
                                        }
                                    }
                                    button {
                                        class: "ghost",
                                        r#type: "button",
                                        disabled: pending(),
                                        onclick: move |_| drop_view(delete_id.clone()),
                                        "Delete"
                                    }
                                }
                            }
                        }
                    }
                }
            }
            if adding() {
                form { style: "margin-top:.8rem;border-top:1px solid var(--border);padding-top:.8rem", onsubmit: save,
                    div { class: "field-grid",
                        div { class: "field",
                            label { r#for: "view-name", "Name" }
                            input {
                                id: "view-name",
                                r#type: "text",
                                value: "{name}",
                                oninput: move |e| name.set(e.value()),
                            }
                        }
                        div { class: "field",
                            label { r#for: "view-share", "Share with" }
                            select {
                                id: "view-share",
                                value: "{share_to}",
                                oninput: move |e| share_to.set(e.value()),
                                option { value: "", "Just me" }
                                for sector in scope.read().sectors.iter() {
                                    option { key: "{sector.id}", value: "{sector.id}", "{sector.name}" }
                                }
                            }
                        }
                    }
                    div { class: "mini-label", style: "margin-top:0", "Widgets" }
                    div { style: "display:flex;gap:.8rem;flex-wrap:wrap;margin-bottom:.6rem",
                        for (kind, label, _) in WIDGET_CATALOGUE {
                            label { key: "{kind}", style: "display:flex;align-items:center;gap:.3rem",
                                input {
                                    r#type: "checkbox",
                                    checked: chosen().iter().any(|c| c == kind),
                                    onchange: move |e| {
                                        let mut picked = chosen();
                                        if e.checked() {
                                            if !picked.iter().any(|c| c == kind) {
                                                picked.push(kind.to_owned());
                                            }
                                        } else {
                                            picked.retain(|c| c != kind);
                                        }
                                        chosen.set(picked);
                                    },
                                }
                                "{label}"
                            }
                        }
                    }
                    p { class: "muted", style: "font-size:.78rem",
                        "Making a view your default changes which widgets the dashboard opens with."
                    }
                    button { class: "primary", r#type: "submit", disabled: pending(), "Save view" }
                }
            }
        }
    }
}

/// The viewer's own favorites, recents and follows.
///
/// Three finished endpoints with no consumer. Recents are written by the story
/// editor as a breadcrumb; favorites and follows are pinned there too. Nothing is
/// rendered when all three are empty, so a new account sees the dashboard it had
/// rather than three empty shelves.
#[component]
fn PersonalShelf() -> Element {
    let session = use_context::<Signal<Option<Session>>>();
    let mut reload = use_signal(|| 0_u32);

    let favorites = use_resource(move || async move {
        reload();
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::favorites(s.access_token).await.map(Some),
        }
    });
    let recents = use_resource(move || async move {
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::recents(s.access_token).await.map(Some),
        }
    });
    let follows = use_resource(move || async move {
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::follows(s.access_token).await.map(Some),
        }
    });

    let favorite_rows = match &*favorites.read_unchecked() {
        Some(Ok(Some(rows))) => rows.clone(),
        _ => Vec::new(),
    };
    let recent_rows = match &*recents.read_unchecked() {
        Some(Ok(Some(rows))) => rows.clone(),
        _ => Vec::new(),
    };
    let follow_count = match &*follows.read_unchecked() {
        Some(Ok(Some(rows))) => rows.len(),
        _ => 0,
    };

    if favorite_rows.is_empty() && recent_rows.is_empty() && follow_count == 0 {
        return rsx! {};
    }

    rsx! {
        div { class: "grid-2", style: "margin-bottom:1.25rem",
            if !favorite_rows.is_empty() {
                div { class: "card widget",
                    div { class: "spread", h3 { "★ Pinned" } span { class: "muted", style: "font-size:.8rem", "{favorite_rows.len()}" } }
                    ul { class: "rowlist",
                        for favorite in favorite_rows.iter() {
                            li { key: "{favorite.entity_type}-{favorite.entity_id}", class: "rowitem",
                                if favorite.entity_type == "story" {
                                    Link {
                                        to: Route::StoryEditor { id: favorite.entity_id.clone() },
                                        class: "grow",
                                        "{favorite.label}"
                                    }
                                } else {
                                    span { class: "grow", "{favorite.label}" }
                                }
                                span { class: "badge", "{favorite.entity_type}" }
                                {
                                    let (etype, eid) = (favorite.entity_type.clone(), favorite.entity_id.clone());
                                    rsx! {
                                        button {
                                            class: "ghost",
                                            r#type: "button",
                                            style: "padding:.1rem .45rem;font-size:.8rem",
                                            title: "Unpin",
                                            onclick: move |_| {
                                                let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else { return; };
                                                let (etype, eid) = (etype.clone(), eid.clone());
                                                spawn(async move {
                                                    if api::remove_favorite(token, etype, eid).await.is_ok() {
                                                        reload += 1;
                                                    }
                                                });
                                            },
                                            "✕"
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            if !recent_rows.is_empty() {
                div { class: "card widget",
                    div { class: "card-h",
                        h3 { "Recently opened" }
                        if follow_count > 0 {
                            Link { to: Route::Following {}, class: "muted", style: "font-size:.8rem", "following {follow_count}" }
                        }
                    }
                    div { class: "recent-grid",
                        for recent in recent_rows.iter().take(6) {
                            if recent.entity_type == "story" {
                                Link {
                                    key: "{recent.entity_type}-{recent.entity_id}",
                                    to: Route::StoryEditor { id: recent.entity_id.clone() },
                                    class: "recent-card",
                                    span { class: "recent-ico", Icon { name: "editor" } }
                                    span { class: "recent-title", "{recent.title}" }
                                    if let Some(at) = &recent.visited_at {
                                        span { class: "recent-when", "{at.get(0..16).unwrap_or(at)}" }
                                    }
                                }
                            } else {
                                div {
                                    key: "{recent.entity_type}-{recent.entity_id}",
                                    class: "recent-card",
                                    span { class: "recent-ico", Icon { name: "grid" } }
                                    span { class: "recent-title", "{recent.title}" }
                                    if let Some(at) = &recent.visited_at {
                                        span { class: "recent-when", "{at.get(0..16).unwrap_or(at)}" }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

/// The computed attention queue: pending/overdue reviews, overdue tasks, open
/// corrections and failed releases, derived on read by four SQL detectors.
///
/// The dashboard previously rendered a fixed "✓ You're clear for now" with no
/// request behind it — an operational claim asserted from nothing. Now the clear
/// state is only shown when the backend actually returns an empty queue.
#[component]
fn AttentionQueue() -> Element {
    let session = use_context::<Signal<Option<Session>>>();
    let mut reload = use_signal(|| 0_u32);
    let mut open_id = use_signal(|| None::<String>);
    let items = use_resource(move || async move {
        reload();
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::attention(s.access_token).await.map(Some),
        }
    });

    match &*items.read_unchecked() {
        Some(Ok(Some(rows))) if rows.is_empty() => rsx! {
            p { class: "attention",
                "✓ Clear right now — the queue returned no reviews, blockers or overdue assignments."
            }
        },
        Some(Ok(Some(rows))) => {
            let sel = open_id().and_then(|oid| rows.iter().find(|i| i.id == oid).cloned());
            rsx! {
                ul { class: "aq-list",
                    for item in rows.iter() {
                        {
                            let sev = match item.severity.as_str() { "critical" => "aq-sev crit", "high" => "aq-sev high", _ => "aq-sev" };
                            let id = item.id.clone();
                            rsx! {
                                li { key: "{item.id}", class: "aq-row",
                                    span { class: "{sev}", "{item.severity}" }
                                    div { class: "aq-body",
                                        div { class: "aq-title", "{item.title}" }
                                        if !item.description.is_empty() {
                                            div { class: "aq-desc", "{item.description}" }
                                        }
                                    }
                                    button { class: "aq-details", r#type: "button",
                                        onclick: move |_| open_id.set(Some(id.clone())),
                                        "Details"
                                    }
                                }
                            }
                        }
                    }
                }
                if let Some(item) = sel {
                    {
                        let sev = match item.severity.as_str() { "critical" => "aq-sev crit", "high" => "aq-sev high", _ => "aq-sev" };
                        let (ack_id, snooze_id, assign_id, esc_id) = (item.id.clone(), item.id.clone(), item.id.clone(), item.id.clone());
                        rsx! {
                            div { class: "sheet-backdrop", onclick: move |_| open_id.set(None),
                                div { class: "sheet", onclick: move |e| e.stop_propagation(),
                                    header { class: "sheet-head",
                                        h3 { "Attention item" }
                                        button { class: "sheet-x", r#type: "button", aria_label: "Close", onclick: move |_| open_id.set(None), "\u{2715}" }
                                    }
                                    div { class: "sheet-body",
                                        span { class: "{sev}", style: "align-self:flex-start", "{item.severity}" }
                                        h4 { class: "aq-sheet-title", "{item.title}" }
                                        if !item.description.is_empty() {
                                            p { class: "aq-sheet-desc", "{item.description}" }
                                        }
                                    }
                                    footer { class: "sheet-foot aq-actions",
                                        button { class: "ei-ghost", r#type: "button",
                                            onclick: move |_| { let Some(t)=session.read().as_ref().map(|s|s.access_token.clone()) else {return;}; let fp=ack_id.clone(); spawn(async move { if api::acknowledge_attention(t, fp).await.is_ok() { reload += 1; open_id.set(None); } }); },
                                            if item.acknowledged { "Acked" } else { "Ack" }
                                        }
                                        button { class: "ei-ghost", r#type: "button",
                                            onclick: move |_| { let Some(t)=session.read().as_ref().map(|s|s.access_token.clone()) else {return;}; let fp=snooze_id.clone(); spawn(async move { if api::snooze_attention(t, fp, 24.0).await.is_ok() { reload += 1; open_id.set(None); } }); },
                                            "Snooze 1d"
                                        }
                                        button { class: "ei-ghost", r#type: "button",
                                            onclick: move |_| { let Some(c)=session.read().clone() else {return;}; let fp=assign_id.clone(); spawn(async move { if api::assign_attention(c.access_token, fp, c.user.id).await.is_ok() { reload += 1; open_id.set(None); } }); },
                                            "Assign to me"
                                        }
                                        button { class: "ei-cta", r#type: "button",
                                            onclick: move |_| { let Some(t)=session.read().as_ref().map(|s|s.access_token.clone()) else {return;}; let fp=esc_id.clone(); spawn(async move { if api::escalate_attention(t, fp).await.is_ok() { reload += 1; open_id.set(None); } }); },
                                            "Escalate"
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        },
        Some(Ok(None)) => rsx! { p { class: "state", "Sign in to see your queue." } },
        Some(Err(message)) => rsx! { p { class: "state error", "Could not load the queue: {message}" } },
        None => rsx! { p { class: "state", "Loading your attention queue…" } },
    }
}

/// The notification kinds the newsroom emits, mirroring the `notify()` call sites
/// in `crates/newsroom/src`.
///
/// Held here because the wasm target does not depend on `meridian-newsroom`. The
/// screen unions this with whatever kinds the backend already has rows for, so a
/// kind added on the server still appears rather than silently vanishing from the
/// user's control.
const NOTIFICATION_KINDS: [&str; 12] = [
    "attention.assigned",
    "desk.invitation",
    "escalation",
    "mention",
    "overdue_story",
    "overdue_task",
    "pitch.created",
    "review",
    "review.decided",
    "review.requested",
    "story.assigned",
    "task.assigned",
];

/// Mirrors `notification_preferences_digest_check` in migration 0008. Values
/// outside this set are rejected by the database, so the list is not a style
/// choice — it is the schema.
const DIGEST_CADENCES: [&str; 4] = ["immediate", "hourly", "daily", "off"];
/// Mirrors `notification_preferences_min_priority_check`.
const PRIORITY_FLOORS: [&str; 4] = ["low", "normal", "high", "critical"];

/// `/settings/notifications` — per-kind delivery preferences.
///
/// `notification_preferences` was fully built and had no UI. The endpoint is a
/// PUT over the whole set, so this screen always sends every row: a partial send
/// would silently drop the kinds it omitted.
#[component]
fn NotificationSettings() -> Element {
    let session = use_context::<Signal<Option<Session>>>();
    let mut rows = use_signal(Vec::<api::PreferenceRow>::new);
    let mut loaded = use_signal(|| false);
    let mut status = use_signal(|| None::<String>);
    let mut saving = use_signal(|| false);

    // Seed from the backend, then fill in any kind that has no row yet with the
    // backend's own documented defaults (in-app on, immediate, low floor).
    use_future(move || async move {
        let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
            return;
        };
        let existing = api::notification_preferences(token).await.unwrap_or_default();
        let mut merged: Vec<api::PreferenceRow> = Vec::new();
        for kind in NOTIFICATION_KINDS {
            let row = existing.iter().find(|r| r.kind == kind).cloned();
            merged.push(row.unwrap_or(api::PreferenceRow {
                kind: kind.to_owned(),
                in_app: true,
                digest: "immediate".to_owned(),
                min_priority: "low".to_owned(),
            }));
        }
        // Any kind the server knows about that this build does not.
        for row in existing {
            if !merged.iter().any(|r| r.kind == row.kind) {
                merged.push(row);
            }
        }
        rows.set(merged);
        loaded.set(true);
    });

    let save = move |_| {
        if saving() {
            return;
        }
        let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
            return;
        };
        let entries = rows();
        saving.set(true);
        status.set(None);
        spawn(async move {
            match api::set_notification_preferences(token, entries).await {
                Ok(()) => status.set(Some("Saved.".to_owned())),
                Err(message) => status.set(Some(message)),
            }
            saving.set(false);
        });
    };

    rsx! {
        Guard { title: "Notification settings",
            div { class: "page-head",
                div {
                    p { class: "eyebrow",
                        Link { to: Route::Settings {}, class: "linklike", "← Settings" }
                        "  ·  Personal"
                    }
                    h1 { class: "page-title", "Notifications" }
                    p { class: "page-sub", "What reaches you, how often, and from which priority up." }
                }
            }
            if loaded() {
                table { class: "table",
                    thead {
                        tr {
                            th { "Event" }
                            th { "In app" }
                            th { "Digest" }
                            th { "Minimum priority" }
                        }
                    }
                    tbody {
                        for (index, row) in rows().iter().enumerate() {
                            tr { key: "{row.kind}",
                                td { style: "font-family:var(--font-mono);font-size:.85rem", "{row.kind}" }
                                td {
                                    input {
                                        r#type: "checkbox",
                                        checked: row.in_app,
                                        "aria-label": "In-app notifications for {row.kind}",
                                        onchange: move |event| {
                                            let on = event.checked();
                                            if let Some(entry) = rows.write().get_mut(index) {
                                                entry.in_app = on;
                                            }
                                        },
                                    }
                                }
                                td {
                                    select {
                                        value: "{row.digest}",
                                        "aria-label": "Digest cadence for {row.kind}",
                                        oninput: move |event| {
                                            let value = event.value();
                                            if let Some(entry) = rows.write().get_mut(index) {
                                                entry.digest = value;
                                            }
                                        },
                                        for cadence in DIGEST_CADENCES {
                                            option { key: "{cadence}", value: "{cadence}", "{cadence}" }
                                        }
                                    }
                                }
                                td {
                                    select {
                                        value: "{row.min_priority}",
                                        "aria-label": "Minimum priority for {row.kind}",
                                        oninput: move |event| {
                                            let value = event.value();
                                            if let Some(entry) = rows.write().get_mut(index) {
                                                entry.min_priority = value;
                                            }
                                        },
                                        for floor in PRIORITY_FLOORS {
                                            option { key: "{floor}", value: "{floor}", "{floor}" }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                div { class: "editor-actions",
                    button { class: "primary", r#type: "button", disabled: saving(), onclick: save,
                        if saving() { "Saving…" } else { "Save preferences" }
                    }
                    if let Some(message) = status() {
                        span { class: "form-note", role: "status", "{message}" }
                    }
                }
            } else {
                p { class: "state", "Loading your preferences…" }
            }
        }
    }
}

/// The notification centre. Backed by `awareness.rs`, which was fully built and
/// had no UI at all.
#[component]
/// A dashboard mini-calendar for the current month, today highlighted. Rendered
/// client-side (via [`CALENDAR_JS`]) to avoid a date dependency on the Rust side.
fn MiniCalendar() -> Element {
    use_effect(|| {
        #[cfg(feature = "web")]
        {
            let _ = document::eval(CALENDAR_JS);
        }
    });
    rsx! {
        div { class: "card widget",
            div { class: "card-h",
                h3 { "Schedule" }
                span { id: "dash-cal-title", class: "muted", "" }
            }
            div { id: "dash-cal", class: "mini-cal" }
        }
    }
}

/// The dedicated notifications page: the full inbox with all/unread filtering,
/// per-item and bulk mark-read, deep links to the related entity, and an opt-in to
/// OS desktop alerts. Backed by the same `/api/v1/notifications` API as the panel.
#[component]
fn NotificationCenter() -> Element {
    let session = use_context::<Signal<Option<Session>>>();
    let navigator = use_navigator();
    let mut reload = use_signal(|| 0_u32);
    let mut unread_only = use_signal(|| false);
    // `.set()` is web-only (inside a `cfg(feature = "web")` block below), so the
    // server build never mutates it; allow the unused `mut` there rather than drop it.
    #[cfg_attr(not(feature = "web"), allow(unused_mut))]
    let mut alert_state = use_signal(|| String::new());
    let items = use_resource(move || async move {
        reload();
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::notifications(s.access_token).await.map(Some),
        }
    });

    rsx! {
        Guard { title: "Notifications",
            div { class: "page-head",
                div {
                    p { class: "eyebrow", "Inbox" }
                    h1 { class: "page-title", "Notifications" }
                    p { class: "page-sub", "Everything the newsroom flagged for you — assignments, approvals, corrections, mentions." }
                }
                div { class: "head-actions",
                    button {
                        class: "ghost",
                        r#type: "button",
                        title: "Show OS desktop alerts for new notifications",
                        onclick: move |_| {
                            #[cfg(feature = "web")]
                            {
                                let mut eval = document::eval(NOTIFY_PERMISSION_JS);
                                spawn(async move {
                                    if let Ok(result) = eval.recv::<String>().await {
                                        alert_state.set(match result.as_str() {
                                            "granted" => "Desktop alerts on.".to_owned(),
                                            "denied" => "Desktop alerts blocked in your browser.".to_owned(),
                                            other => format!("Desktop alerts: {other}"),
                                        });
                                    }
                                });
                            }
                        },
                        Icon { name: "bell" }
                        "Enable desktop alerts"
                    }
                    button {
                        class: "primary",
                        r#type: "button",
                        onclick: move |_| {
                            let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else { return; };
                            spawn(async move {
                                if api::mark_all_notifications_read(token).await.is_ok() { reload += 1; }
                            });
                        },
                        Icon { name: "check" }
                        "Mark all read"
                    }
                }
            }
            if !alert_state().is_empty() {
                p { class: "muted", style: "margin-bottom:1rem", "{alert_state}" }
            }
            div { class: "segmented", style: "margin-bottom:1.25rem",
                button {
                    class: if unread_only() { "seg-btn" } else { "seg-btn active" },
                    r#type: "button",
                    onclick: move |_| unread_only.set(false),
                    "All"
                }
                button {
                    class: if unread_only() { "seg-btn active" } else { "seg-btn" },
                    r#type: "button",
                    onclick: move |_| unread_only.set(true),
                    "Unread"
                }
            }
            match &*items.read_unchecked() {
                Some(Ok(Some(rows))) => {
                    let shown: Vec<_> = rows.iter().filter(|n| !unread_only() || n.read_at.is_none()).collect();
                    if shown.is_empty() {
                        rsx! { div { class: "card", p { class: "muted", style: "text-align:center;padding:1.5rem",
                            if unread_only() { "You're all caught up." } else { "No notifications yet." }
                        } } }
                    } else {
                        rsx! {
                            ul { class: "notif-list",
                                for note in shown {
                                    li {
                                        key: "{note.id}",
                                        class: if note.read_at.is_some() { "notif read" } else { "notif" },
                                        onclick: {
                                            let route = notif_route(note.entity_type.as_deref(), note.entity_id.as_deref());
                                            let id = note.id.clone();
                                            let already = note.read_at.is_some();
                                            move |_| {
                                                if !already {
                                                    if let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) {
                                                        let id = id.clone();
                                                        spawn(async move { let _ = api::mark_notification_read(token, id).await; reload += 1; });
                                                    }
                                                }
                                                if let Some(route) = route.clone() { navigator.push(route); }
                                            }
                                        },
                                        span { class: "notif-ico", Icon { name: notif_icon(&note.kind) } }
                                        div { class: "notif-body",
                                            div { class: "notif-top",
                                                span { class: "notif-title", "{note.title}" }
                                                if note.priority == "high" || note.priority == "urgent" {
                                                    span { class: "badge warning", "{note.priority}" }
                                                }
                                            }
                                            if let Some(body) = note.body.as_ref() {
                                                div { class: "notif-text", "{body}" }
                                            }
                                            div { class: "notif-meta",
                                                span { "{note.kind.replace('_', \" \")}" }
                                                span { "·" }
                                                span { "{note.created_at.get(0..16).unwrap_or(&note.created_at)}" }
                                            }
                                        }
                                        if note.read_at.is_none() {
                                            span { class: "notif-dot", aria_label: "unread" }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                Some(Err(message)) => rsx! { div { class: "card", p { class: "state error", "Could not load notifications: {message}" } } },
                _ => rsx! { div { class: "card", p { class: "state", "Loading notifications…" } } },
            }
        }
    }
}

/// Maps a notification's `kind` to a glyph.
fn notif_icon(kind: &str) -> &'static str {
    let k = kind.to_ascii_lowercase();
    if k.contains("assign") || k.contains("task") {
        "editor"
    } else if k.contains("approve") || k.contains("ready") || k.contains("publish") {
        "check"
    } else if k.contains("correct") {
        "bell"
    } else if k.contains("mention") || k.contains("comment") || k.contains("reply") {
        "feed"
    } else if k.contains("invite") {
        "invitations"
    } else {
        "bell"
    }
}

/// The in-app destination for a notification's linked entity, if any.
fn notif_route(entity_type: Option<&str>, entity_id: Option<&str>) -> Option<Route> {
    match (entity_type, entity_id) {
        (Some("story"), Some(id)) => Some(Route::StoryEditor { id: id.to_owned() }),
        _ => None,
    }
}

// Unwired: superseded by NotificationCenter. Kept for now; delete or re-wire.
#[allow(dead_code, non_snake_case)]
fn NotificationPanel() -> Element {
    let session = use_context::<Signal<Option<Session>>>();
    let mut reload = use_signal(|| 0_u32);
    let items = use_resource(move || async move {
        reload();
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::notifications(s.access_token).await.map(Some),
        }
    });

    rsx! {
        div { class: "spread",
            h3 { style: "margin:0", "Notifications" }
            button {
                class: "ghost",
                r#type: "button",
                style: "padding:.25rem .6rem",
                onclick: move |_| {
                    let Some(token) = session.read().as_ref().map(|s| s.access_token.clone()) else {
                        return;
                    };
                    spawn(async move {
                        if api::mark_all_notifications_read(token).await.is_ok() {
                            reload += 1;
                        }
                    });
                },
                "Mark all read"
            }
        }
        match &*items.read_unchecked() {
            Some(Ok(Some(rows))) if rows.is_empty() => rsx! {
                p { class: "muted", style: "font-size:.85rem", "Nothing new." }
            },
            Some(Ok(Some(rows))) => rsx! {
                ul { class: "rowlist",
                    for note in rows.iter() {
                        li { key: "{note.id}", class: "rowitem",
                            div { class: "grow",
                                div {
                                    style: if note.read_at.is_some() {
                                        "font-weight:500;opacity:.65"
                                    } else {
                                        "font-weight:650"
                                    },
                                    "{note.title}"
                                }
                                if let Some(body) = note.body.as_ref() {
                                    div { class: "muted", style: "font-size:.8rem", "{body}" }
                                }
                            }
                            if note.read_at.is_none() {
                                button {
                                    class: "ghost",
                                    r#type: "button",
                                    style: "padding:.2rem .5rem",
                                    onclick: {
                                        let id = note.id.clone();
                                        move |_| {
                                            let Some(token) =
                                                session.read().as_ref().map(|s| s.access_token.clone())
                                            else {
                                                return;
                                            };
                                            let id = id.clone();
                                            spawn(async move {
                                                if api::mark_notification_read(token, id).await.is_ok() {
                                                    reload += 1;
                                                }
                                            });
                                        }
                                    },
                                    "Read"
                                }
                            }
                        }
                    }
                }
            },
            Some(Ok(None)) => rsx! { p { class: "muted", style: "font-size:.85rem", "Sign in to see notifications." } },
            Some(Err(message)) => rsx! { p { class: "state error", "{message}" } },
            None => rsx! { p { class: "muted", style: "font-size:.85rem", "Loading…" } },
        }
    }
}

/// Cycles System → Light → Dark. The choice is written to `<html data-theme>`
/// and remembered in browser storage; "System" removes the attribute so the OS
/// preference takes over again.
#[component]
fn ThemeToggle() -> Element {
    let mut theme = use_signal(|| meridian_ui::Theme::System);

    // Adopt the stored preference once, so a reload does not flash the default.
    use_effect(move || {
        let stored = stored_theme();
        if stored != meridian_ui::Theme::System {
            theme.set(stored);
        }
    });

    rsx! {
        button {
            class: "ghost",
            r#type: "button",
            onclick: move |_| {
                let next = theme().next();
                theme.set(next);
                document::eval(&meridian_ui::apply_theme_script(next));
            },
            "{theme().label()}"
        }
    }
}

#[cfg(feature = "web")]
fn stored_theme() -> meridian_ui::Theme {
    use gloo_storage::{LocalStorage, Storage};
    // No stored preference ⇒ the house default (sepia), not the OS setting.
    LocalStorage::get::<String>("meridian.theme")
        .map_or(meridian_ui::DEFAULT_THEME, |value| {
            meridian_ui::Theme::from_stored(&value)
        })
}

#[cfg(not(feature = "web"))]
fn stored_theme() -> meridian_ui::Theme {
    meridian_ui::DEFAULT_THEME
}

// --- Lock screen ----------------------------------------------------------

/// The five lock-screen wallpapers: `(display name, spotlight caption)`. The image
/// for each is [`LOCK_BGS`] at the same index — a curated set of monochrome editorial
/// photographs, bundled same-origin so the whole thing works under the strict CSP.
const LOCK_WALLPAPERS: [(&str, &str); 5] = [
    ("The Desk", "Where the story starts — a blank page and a good coffee."),
    ("The Skyline", "The city we cover, from above."),
    ("The Tower", "Steel and glass, the business of the day."),
    ("The Pavilion", "Clean lines, quiet light — the culture beat."),
    ("The Passage", "Every road out is a road to a story."),
];

/// localStorage key for the chosen wallpaper index; default 2 (The Tower), a moody
/// mid-key architectural frame that flatters the white chrome.
#[cfg(feature = "web")]
fn stored_lock_wallpaper() -> usize {
    use gloo_storage::{LocalStorage, Storage};
    LocalStorage::get::<String>("meridian.lockWallpaper")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|index| *index < LOCK_WALLPAPERS.len())
        .unwrap_or(2)
}

#[cfg(feature = "web")]
fn store_lock_wallpaper(index: usize) {
    use gloo_storage::{LocalStorage, Storage};
    let _ = LocalStorage::set("meridian.lockWallpaper", index.to_string());
}


/// Whether the lock screen gates the sign-in view. Defaults on; only an explicit
/// `"false"` disables it.
#[cfg(feature = "web")]
fn lock_enabled() -> bool {
    use gloo_storage::{LocalStorage, Storage};
    LocalStorage::get::<String>("meridian.lockEnabled").map_or(true, |value| value != "false")
}

#[cfg(feature = "web")]
fn set_lock_enabled(enabled: bool) {
    use gloo_storage::{LocalStorage, Storage};
    let _ = LocalStorage::set(
        "meridian.lockEnabled",
        if enabled { "true" } else { "false" },
    );
}

#[cfg(not(feature = "web"))]
fn stored_lock_wallpaper() -> usize {
    2
}
#[cfg(not(feature = "web"))]
fn store_lock_wallpaper(_index: usize) {}
#[cfg(not(feature = "web"))]
fn lock_enabled() -> bool {
    true
}
#[cfg(not(feature = "web"))]
fn set_lock_enabled(_enabled: bool) {}

// --- Typography schemes ---------------------------------------------------

/// Selectable font schemes: `(key, display name, tagline subtitle)`. The CSS for
/// each lives in `tokens.css` under `:root[data-font="<key>"]`. Applied by stamping
/// `data-font` on `<html>`, mirroring the theme toggle; default is `editorial`.
const FONT_SCHEMES: [(&str, &str, &str); 4] = [
    ("wire", "Wire", "Newsreader \u{00b7} Inter"),
    ("broadsheet", "Broadsheet", "Fraunces \u{00b7} Inter"),
    ("grotesque", "Grotesque", "Inter"),
    ("humanist", "Humanist", "Newsreader \u{00b7} Optima"),
];

#[cfg(feature = "web")]
fn stored_font() -> String {
    use gloo_storage::{LocalStorage, Storage};
    LocalStorage::get::<String>("meridian.font")
        .ok()
        .filter(|value| FONT_SCHEMES.iter().any(|(key, _, _)| key == value))
        .unwrap_or_else(|| "wire".to_owned())
}

#[cfg(feature = "web")]
fn apply_font(scheme: &str) {
    use gloo_storage::{LocalStorage, Storage};
    let _ = LocalStorage::set("meridian.font", scheme);
    let _ = document::eval(&format!(
        "document.documentElement.setAttribute('data-font', {scheme:?});"
    ));
}

#[cfg(not(feature = "web"))]
fn stored_font() -> String {
    "wire".to_owned()
}
#[cfg(not(feature = "web"))]
fn apply_font(_scheme: &str) {}

/// Injects a workspace brand by overriding the design tokens at runtime: the
/// accent recolours `--accent-brand`/`--ring`, the ink tints the masthead. Passing
/// `None` clears the override, falling back to the built-in wire-service tokens.
#[cfg(feature = "web")]
fn apply_brand(accent: Option<&str>, ink: Option<&str>) {
    fn one(var: &str, val: Option<&str>) -> String {
        match val {
            Some(v) if !v.trim().is_empty() => format!("r.setProperty('{var}', {v:?});"),
            _ => format!("r.removeProperty('{var}');"),
        }
    }
    let js = format!(
        "var r=document.documentElement.style; {} {} {}",
        one("--accent-brand", accent),
        one("--ring", accent),
        one("--brand-ink", ink),
    );
    let _ = document::eval(&js);
}
#[cfg(not(feature = "web"))]
fn apply_brand(_accent: Option<&str>, _ink: Option<&str>) {}

/// Requests OS desktop-notification permission and, when granted, fires a
/// confirmation notification. Reports the resulting permission back to Rust via
/// the eval channel. This is the foreground half of push — real background push
/// (delivered while the tab is closed) additionally needs a service worker and
/// VAPID keys on the server.
#[cfg(feature = "web")]
const NOTIFY_PERMISSION_JS: &str = r#"
if (!('Notification' in window)) { dioxus.send('unsupported'); }
else if (Notification.permission === 'granted') {
  try { new Notification('iGEN News', { body: 'Desktop alerts are on.' }); } catch (e) {}
  dioxus.send('granted');
} else if (Notification.permission === 'denied') {
  dioxus.send('denied');
} else {
  Notification.requestPermission().then(function (p) {
    if (p === 'granted') { try { new Notification('iGEN News', { body: 'Desktop alerts are on.' }); } catch (e) {} }
    dioxus.send(p);
  }).catch(function () { dioxus.send('error'); });
}
"#;

/// Fills the dashboard mini-calendar with the current month, today highlighted.
/// Self-contained (no date lib on the Rust side); only writes into its own nodes.
#[cfg(feature = "web")]
const CALENDAR_JS: &str = r#"
(function () {
  var el = document.getElementById('dash-cal');
  if (!el) return;
  var now = new Date();
  var y = now.getFullYear(), m = now.getMonth(), today = now.getDate();
  var startDow = (new Date(y, m, 1).getDay() + 6) % 7;
  var days = new Date(y, m + 1, 0).getDate();
  var dows = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];
  var html = '';
  for (var i = 0; i < 7; i++) html += '<span class="cw">' + dows[i] + '</span>';
  for (var b = 0; b < startDow; b++) html += '<span></span>';
  for (var d = 1; d <= days; d++) html += '<span class="cd' + (d === today ? ' on' : '') + '">' + d + '</span>';
  el.innerHTML = html;
  var title = document.getElementById('dash-cal-title');
  if (title) { try { title.textContent = now.toLocaleDateString(undefined, { month: 'long', year: 'numeric' }); } catch (e) {} }
})();
"#;

/// Drives the lock-screen clock/date. Self-clearing: it stops when `#lock-clock`
/// leaves the DOM, and it clears any prior interval first so a remount never
/// stacks tickers. Only writes text into the two lock elements — it never touches
/// the router or anything else.
#[cfg(feature = "web")]
const LOCK_TICK_JS: &str = r#"
(function(){
  if (window.__meridianLockTick) { clearInterval(window.__meridianLockTick); window.__meridianLockTick = null; }
  function pad(n){ return n < 10 ? '0' + n : '' + n; }
  function upd(){
    var c = document.getElementById('lock-clock');
    if (!c) { if (window.__meridianLockTick) { clearInterval(window.__meridianLockTick); window.__meridianLockTick = null; } return; }
    var d = new Date();
    c.textContent = pad(d.getHours()) + ':' + pad(d.getMinutes());
    var dt = document.getElementById('lock-date');
    if (dt) { try { dt.textContent = d.toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' }); } catch (e) { dt.textContent = d.toDateString(); } }
  }
  upd();
  window.__meridianLockTick = setInterval(upd, 1000);
})();
"#;

/// Where "back to stories" goes from a screen that carries no sector of its own:
/// the active sector's list, or the sector index when the viewer is org-wide.
fn stories_route(scope: &SectorScope) -> Route {
    scope
        .active_slug()
        .map_or(Route::Workspaces {}, |sector| Route::Stories { sector })
}

fn tasks_route(scope: &SectorScope) -> Route {
    scope
        .active_slug()
        .map_or(Route::Workspaces {}, |sector| Route::TasksBoard { sector })
}

fn planning_route(scope: &SectorScope) -> Route {
    scope
        .active_slug()
        .map_or(Route::Workspaces {}, |sector| Route::Planning { sector })
}

/// A stable colour per sector, derived from its slug so the same sector always
/// reads the same without storing a colour the backend does not have.
fn sector_color(slug: &str) -> String {
    // Pure black & white: a stable grey per sector (no hue), varied only in lightness
    // so monograms stay distinguishable while the palette remains monochrome.
    let h = slug.bytes().fold(0u32, |acc, byte| acc.wrapping_mul(31).wrapping_add(u32::from(byte)));
    let light = 0.16 + f64::from(h % 6) * 0.052;
    format!("oklch({light:.3} 0 0)")
}

/// The sector a route belongs to, if it is a sector-scoped screen.
///
/// The sidebar's sector nav is driven by *being inside* a sector — read straight
/// from the URL — not by a pinned per-sector tab. A person can hold hundreds of
/// sectors, so none of them may live in the fixed workspace switcher; they are
/// reached through the "Sectors" list, and the screen you land on tells the sidebar
/// which sector's nav to show.
fn route_sector_slug(route: &Route) -> Option<String> {
    match route {
        Route::SectorDashboard { sector }
        | Route::Stories { sector }
        | Route::TasksBoard { sector }
        | Route::Planning { sector }
        | Route::SectorSettings { sector }
        | Route::SectorAssets { sector }
        | Route::SectorTeam { sector }
        | Route::SectorAnalytics { sector }
        | Route::SectorSearch { sector }
        | Route::ReviewConsole { sector, .. }
        | Route::VerificationConsole { sector, .. }
        | Route::PublishingConsole { sector, .. } => Some(sector.clone()),
        _ => None,
    }
}

/// The workspace zone a route belongs to — the single source of truth for which
/// context the sidebar and topbar show. Derived from the route itself (not a stored
/// selection), so a deep link, a refresh or a direct navigation always lands in the
/// matching context. Note the zone is not a URL prefix: "My pitches" and the feed are
/// `/org/…` yet belong to the reader's Personal zone.
fn route_zone(route: &Route) -> &'static str {
    if route_sector_slug(route).is_some() {
        return "sector";
    }
    match route {
        Route::Admin {}
        | Route::RolesAdmin {}
        | Route::Governance {}
        | Route::WebhooksAdmin {}
        | Route::SectorAdmin {}
        | Route::SectorMembers { .. }
        | Route::SectorProfile { .. }
        | Route::SectorApplications {}
        | Route::AdminUserConsole { .. } => "admin",

        Route::Dashboard {}
        | Route::MyPitches {}
        | Route::Feed {}
        | Route::Invitations {}
        | Route::Settings {}
        | Route::NotificationCenter {}
        | Route::NotificationSettings {}
        | Route::SessionSettings {}
        | Route::Following {}
        | Route::SignIn {}
        | Route::ForgotPassword {}
        | Route::NoAccess {}
        | Route::Onboarding {}
        | Route::MyApplications {}
        | Route::SectorBrowse {}
        | Route::ApplyToSectorPage { .. }
        | Route::PersonProfile { .. }
        | Route::NotFound { .. } => "personal",

        // The cross-sector roll-ups and shared editorial documents.
        _ => "newsroom",
    }
}

#[component]
fn Sidebar() -> Element {
    let session = use_context::<Signal<Option<Session>>>();
    let scope = use_context::<Signal<SectorScope>>();
    let caps = use_context::<Signal<Capabilities>>();
    let drawer = use_context::<DrawerOpen>();
    // The sector nav is driven by the URL, not a stored selection, so it is always
    // the sector actually on screen.
    let route = use_route::<Route>();
    let route_sector = route_sector_slug(&route);
    let (name, role, initial, is_admin) = match session.read().as_ref() {
        Some(s) => {
            let initial = s
                .user
                .display_name
                .chars()
                .next()
                .map_or_else(|| "U".to_owned(), |c| c.to_uppercase().to_string());
            (
                s.user.display_name.clone(),
                s.user.role.clone(),
                initial,
                s.user.is_admin || s.user.role == "admin",
            )
        }
        None => (String::new(), String::new(), "U".to_owned(), false),
    };
    // Org-level permission check. An admin holds everything (matching the server's
    // resolver); everyone else is measured against the capabilities resolved for
    // them. Used only to gate *org-wide* destinations — never the sector nav, whose
    // grants may be desk-scoped and so never appear in this org-level set.
    let can = move |capability: &str| is_admin || caps.read().can(capability);

    // Which fixed contexts this viewer may see. Personal is universal. Newsroom is
    // the cross-sector editorial roll-up — shown to admins, to anyone who belongs to
    // a sector, and to org-level editorial roles. Admin is governance, gated on the
    // management capabilities behind its screens.
    let has_sectors = !scope.read().sectors.is_empty();
    let show_newsroom = is_admin
        || has_sectors
        || caps.read().can_any(&[
            "dashboard.view_audience",
            "releases.publish",
            "stories.create",
            "pitches.decide",
            "reviews.decide_any",
        ]);
    let show_admin = can("permissions.manage")
        || can("roles.manage")
        || can("desks.manage")
        || can("flags.manage");

    // The context is the one the current route belongs to — so the highlighted tab
    // and the nav list always match the screen, whether it was reached by a tab, a
    // deep link or a refresh.
    let ctx = route_zone(&route);
    rsx! {
        aside { class: if drawer.0() { "sidebar is-open" } else { "sidebar" },
            Link { to: Route::Dashboard {}, class: "sidebar-brand", aria_label: "{brand::name()}",
                img { class: "brand-logo", src: BRAND_LOGO, alt: "{brand::name()}" }
            }
            // Workspace switcher: a small, fixed set of role-based contexts so nobody
            // is shown every door at once. Sectors are NOT tabs here — a person can
            // hold hundreds; they live in the "Sectors" list below, and a sector's
            // own nav appears when you're inside it. Clicking a context also lands on
            // its home, which is how you step back out of a sector.
            div { class: "wsw",
                button {
                    r#type: "button",
                    class: if ctx == "personal" { "wsw-tab is-active" } else { "wsw-tab" },
                    onclick: move |_| { navigator().push(Route::Dashboard {}); },
                    "Personal"
                }
                if show_newsroom {
                    button {
                        r#type: "button",
                        class: if ctx == "newsroom" { "wsw-tab is-active" } else { "wsw-tab" },
                        onclick: move |_| { navigator().push(Route::Pitches {}); },
                        "Newsroom"
                    }
                }
                if show_admin {
                    button {
                        r#type: "button",
                        class: if ctx == "admin" { "wsw-tab is-active" } else { "wsw-tab" },
                        onclick: move |_| { navigator().push(Route::Admin {}); },
                        "Admin"
                    }
                }
            }
            nav { aria_label: "Workspace",
                {
                    // Inside a sector, its own nav wins — the slug is the one in the URL,
                    // so this is always the sector on screen. Otherwise the selected
                    // context (Personal / Newsroom / Admin) drives the list.
                    if let Some(slug) = route_sector.clone() {
                        rsx! {
                            NavItem { to: Route::SectorDashboard { sector: slug.clone() }, icon: "dashboard", label: "Sector dashboard" }
                            NavItem { to: Route::Stories { sector: slug.clone() }, icon: "stories", label: "Stories" }
                            NavItem { to: Route::TasksBoard { sector: slug.clone() }, icon: "tasks", label: "Tasks" }
                            NavItem { to: Route::Planning { sector: slug.clone() }, icon: "calendar", label: "Planning calendar" }
                            NavItem { to: Route::SectorSearch { sector: slug.clone() }, icon: "search", label: "Search" }
                            NavItem { to: Route::SectorAssets { sector: slug.clone() }, icon: "assets", label: "Assets" }
                            NavItem { to: Route::SectorTeam { sector: slug.clone() }, icon: "team", label: "Team" }
                            NavItem { to: Route::SectorAnalytics { sector: slug.clone() }, icon: "analytics", label: "Analytics" }
                            NavItem { to: Route::SectorSettings { sector: slug.clone() }, icon: "settings", label: "Sector settings" }
                            NavItem { to: Route::Editor {}, icon: "editor", label: "New story" }
                        }
                    } else {
                        match ctx {
                            // Newsroom roll-ups. The list/read screens are open (the
                            // server scopes their data); only the privileged doors —
                            // Analytics and Publishing — are gated, matching what their
                            // endpoints enforce, so no one is offered a 403.
                            "newsroom" => rsx! {
                                NavItem { to: Route::Workspaces {}, icon: "workspaces", label: "Sectors" }
                                NavItem { to: Route::Pitches {}, icon: "stories", label: "Pitches" }
                                NavItem { to: Route::EditorialIntake {}, icon: "editor", label: "Submit a pitch" }
                                NavItem { to: Route::Team {}, icon: "team", label: "People" }
                                if can("dashboard.view_audience") {
                                    NavItem { to: Route::Analytics {}, icon: "analytics", label: "Analytics" }
                                }
                                NavItem { to: Route::Assets {}, icon: "assets", label: "Asset library" }
                                NavItem { to: Route::LegalDocs {}, icon: "verification", label: "Legal docs" }
                                if can("releases.publish") {
                                    NavItem { to: Route::Publishing {}, icon: "stories", label: "Publishing" }
                                }
                                NavItem { to: Route::FrontPage {}, icon: "dashboard", label: "Front page" }
                            },
                            // Governance. Each door is gated on the exact capability its
                            // screen manages; the zone itself only appears when at least
                            // one of these is held (see `show_admin`).
                            "admin" => rsx! {
                                if can("permissions.manage") {
                                    NavItem { to: Route::Admin {}, icon: "admin", label: "Super Admin" }
                                }
                                if can("roles.manage") {
                                    NavItem { to: Route::RolesAdmin {}, icon: "admin", label: "Roles & permissions" }
                                }
                                if can("permissions.manage") {
                                    NavItem { to: Route::Governance {}, icon: "admin", label: "Governance" }
                                }
                                if can("webhooks.manage") {
                                    NavItem { to: Route::WebhooksAdmin {}, icon: "feed", label: "Webhooks" }
                                }
                                if can("desks.manage") {
                                    NavItem { to: Route::SectorAdmin {}, icon: "workspaces", label: "Sector registry" }
                                }
                            },
                            // Personal — universal; every screen here is the viewer's own.
                            _ => rsx! {
                                NavItem { to: Route::Dashboard {}, icon: "dashboard", label: "Home" }
                                NavItem { to: Route::MyPitches {}, icon: "invitations", label: "My pitches" }
                                NavItem { to: Route::Feed {}, icon: "feed", label: "Newsroom Feed" }
                                NavItem { to: Route::Invitations {}, icon: "invitations", label: "Invitations" }
                                NavItem { to: Route::Settings {}, icon: "settings", label: "Settings" }
                            },
                        }
                    }
                }
            }
            // Sectors: the viewer's workspaces, reached as a list (a person can hold
            // hundreds), never as switcher tabs. The one you open drives the nav above.
            div { class: "sidebar-section", "Sectors" }
            SectorSwitcher {}
            a { class: "sb-promo", href: "/standards",
                span { class: "sb-promo-k", "Trust & standards" }
                span { class: "sb-promo-v", "Verified" }
                span { class: "sb-promo-s", "Corrections, ethics & ownership — public." }
                span { class: "sb-promo-cta", "View report \u{2192}" }
            }
            div { class: "sidebar-account",
                div { class: "who",
                    span { class: "avatar", "{initial}" }
                    div {
                        div { class: "who-name", "{name}" }
                        div { class: "who-role", "{role}" }
                    }
                }
            }
        }
    }
}

#[component]
fn NavItem(to: Route, icon: &'static str, label: &'static str) -> Element {
    // Expose the active item to assistive tech, not just by colour. Exact-match,
    // mirroring the router's own `active_class`.
    let is_active = use_route::<Route>() == to;
    let mut drawer = use_context::<DrawerOpen>();
    rsx! {
        Link {
            to: to,
            class: "nav-item",
            active_class: "active",
            aria_current: if is_active { "page" } else { "false" },
            // Following a link closes the mobile drawer so the content is visible.
            onclick: move |_| drawer.0.set(false),
            span { class: "ico", Icon { name: icon } }
            span { "{label}" }
        }
    }
}

