#[component]
fn Dashboard() -> Element {
    let scope = use_context::<Signal<SectorScope>>();
    let session = use_context::<Signal<Option<Session>>>();
    let signed_out = session.read().is_none();

    let stories = use_resource(move || async move {
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::stories(s.access_token).await.map(Some),
        }
    });
    let summary = use_resource(move || async move {
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::dashboard_summary(s.access_token).await.map(Some),
        }
    });
    let layout = use_resource(move || async move {
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::dashboard_layout(s.access_token).await.map(Some),
        }
    });
    // While the layout is in flight, or if it fails, the catalogue defaults stand
    // in so the dashboard renders its usual self rather than blank. This is a
    // *presentation* default, not substituted data — every widget still fetches
    // its own content from the backend. The server's baseline is this same set,
    // computed from the same catalogue, so the two cannot disagree.
    let widget_order = move || -> Vec<String> {
        match &*layout.read_unchecked() {
            Some(Ok(Some(resolved))) if !resolved.widgets.is_empty() => resolved.types(),
            _ => WIDGET_CATALOGUE
                .iter()
                .filter(|(_, _, on)| *on)
                .map(|(kind, _, _)| (*kind).to_owned())
                .collect(),
        }
    };
    let feed = use_resource(move || async move {
        match session.read().clone() {
            None => Ok(None),
            Some(s) => api::feed(s.access_token).await.map(Some),
        }
    });
    // A signed-out visitor at the root goes straight to the sign-in view — which
    // is itself gated by the lock screen — so the flow is lock → dismiss → login,
    // with no redundant landing page in between. The effect is declared
    // unconditionally (rules of hooks) and only redirects while signed out.
    let root_navigator = use_navigator();
    use_effect(move || {
        if session.read().is_none() {
            root_navigator.replace(Route::SignIn {});
        }
    });
    if signed_out {
        return rsx! { section { class: "panel", p { class: "state loading", "\u{2026}" } } };
    }

    let greeting_name = session
        .read()
        .as_ref()
        .map(|s| s.user.display_name.split_whitespace().next().unwrap_or("").to_owned())
        .unwrap_or_default();

    rsx! {
        section { class: "panel",
            header { class: "dash-welcome",
                div { class: "dw-copy",
                    p { class: "dw-eyebrow", "Your newsroom" }
                    h1 { class: "dw-title", "Good morning, {greeting_name}." }
                    p { class: "dw-sub", "Every story's life — pitch to correction — in one calm workspace." }
                    div { class: "dw-actions",
                        Link { to: Route::Editor {}, class: "dw-cta",
                            Icon { name: "plus" }
                            "New story"
                        }
                    }
                }
                div { class: "dw-art", {dashboard_illustration()} }
            }

            section { class: "qa-block",
                p { class: "qa-eyebrow", "Quick actions" }
                div { class: "qa-grid",
                    Link { to: Route::Editor {}, class: "qa-tile",
                        span { class: "qa-ic", "NS" } span { class: "qa-l", "New story" } }
                    Link { to: Route::EditorialIntake {}, class: "qa-tile",
                        span { class: "qa-ic", "SP" } span { class: "qa-l", "Submit a pitch" } }
                    Link { to: Route::Pitches {}, class: "qa-tile",
                        span { class: "qa-ic", "PI" } span { class: "qa-l", "Pitches" } }
                    Link { to: Route::Workspaces {}, class: "qa-tile",
                        span { class: "qa-ic", "SE" } span { class: "qa-l", "Sectors" } }
                    Link { to: Route::Team {}, class: "qa-tile",
                        span { class: "qa-ic", "PE" } span { class: "qa-l", "People" } }
                    Link { to: Route::Analytics {}, class: "qa-tile",
                        span { class: "qa-ic", "AN" } span { class: "qa-l", "Analytics" } }
                }
            }

            {
                let desks = scope.read().sectors.clone();
                rsx! {
                    if !desks.is_empty() {
                        section { class: "qa-block",
                            div { class: "desk-strip-head",
                                p { class: "qa-eyebrow", style: "margin:0", "Your desks" }
                                Link { to: Route::Workspaces {}, class: "desk-strip-all", "All sectors \u{2192}" }
                            }
                            div { class: "desk-strip",
                                for s in desks.iter() {
                                    Link { key: "{s.id}", to: Route::SectorDashboard { sector: s.slug.clone() }, class: "desk-tile",
                                        span { class: "desk-av", style: "background:{sector_color(&s.slug)}", "{initials(&s.name)}" }
                                        span { class: "desk-name", "{s.name}" }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // The widgets, in the order the resolved layout gives them — the
            // viewer's default saved view if they have one, otherwise the role
            // baseline. `saved_views` is always rendered regardless of the layout,
            // because it is the control that changes the layout: a view that
            // omitted it would leave no way back.
            for kind in widget_order() {
                match kind.as_str() {
                    "summary_metrics" => rsx! {
                        match &*summary.read_unchecked() {
                            Some(Ok(Some(value))) => rsx! { StatRow { summary: value.clone() } },
                            Some(Err(message)) => rsx! { p { class: "state error", "Could not load summary: {message}" } },
                            _ => rsx! { div { class: "stat-row",
                                for i in 0..5 { div { key: "{i}", class: "stat", div { class: "k", "loading" } div { class: "n", "—" } } }
                            } },
                        }
                    },
                    "attention_queue" => rsx! {
                        div { class: "card", style: "margin-bottom:1.25rem",
                            div { class: "widget", h3 { "⚠ Attention Queue" } }
                            AttentionQueue {}
                        }
                    },
                    "drilldowns" => rsx! { Drilldowns {} },
                    "personal_shelf" => rsx! { PersonalShelf {} },
                    // `pipeline` and `activity` are in the catalogue and the
                    // baseline contract but have no standalone widget component
                    // yet; the pipeline is on /org/analytics and activity feeds the
                    // notification centre. Rendering nothing is correct until they
                    // exist — and the catalogue marks both default-off, so no
                    // default layout promises them.
                    _ => rsx! {},
                }
            }

            SavedViews {}

            div { class: "dash-grid",
                div { class: "dash-col",
                    // Pipeline pulse + the attention list, from the real story set.
                    match &*stories.read_unchecked() {
                        Some(Ok(Some(items))) if !items.is_empty() => {
                            let total = items.len();
                            let pipeline: Vec<(&str, usize, usize)> = PIPELINE_STAGES
                                .iter()
                                .map(|(state, _)| {
                                    let count = items.iter().filter(|i| i.workflow_state == *state).count();
                                    let pct = if total > 0 {
                                        ((count * 100 / total).max(if count > 0 { 8 } else { 0 })).min(100)
                                    } else {
                                        0
                                    };
                                    (*state, count, pct)
                                })
                                .collect();
                            rsx! {
                                div { class: "card widget dash-hero",
                                    div { class: "card-h",
                                        h3 { "Pipeline pulse" }
                                        span { class: "muted", "{total} in flight" }
                                    }
                                    {
                                        let counts: Vec<usize> = pipeline.iter().map(|(_, c, _)| *c).collect();
                                        let (area, line) = area_paths(&counts);
                                        rsx! {
                                            div { class: "pulse-chart",
                                                svg { view_box: "0 0 100 100", preserve_aspect_ratio: "none",
                                                    path { d: "{area}", class: "pc-area" }
                                                    path { d: "{line}", class: "pc-line" }
                                                }
                                            }
                                        }
                                    }
                                    div { class: "pulse-bars",
                                        for (state , count , pct) in pipeline {
                                            div { key: "{state}", class: "pulse-bar",
                                                span { class: "pb-label", "{stage_label(state)}" }
                                                div { class: "pb-track",
                                                    div { class: "pb-fill", style: "width:{pct}%" }
                                                }
                                                span { class: "pb-n", "{count}" }
                                            }
                                        }
                                    }
                                }
                                div { class: "card widget",
                                    div { class: "card-h",
                                        h3 { "Needs your attention" }
                                        Link { to: stories_route(&scope.read()), class: "linklike", "All stories →" }
                                    }
                                    ul { class: "rowlist",
                                        for item in items.iter().take(5) {
                                            li { key: "{item.id}", class: "rowitem",
                                                span { class: "av", "{initials(&item.title)}" }
                                                div { class: "grow",
                                                    Link { to: Route::StoryEditor { id: item.id.clone() }, class: "t", "{item.title}" }
                                                    div { class: "s", "{item.priority} priority" }
                                                }
                                                span { class: "badge {stage_tone(&item.workflow_state)}", "{stage_label(&item.workflow_state)}" }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        Some(Ok(Some(_))) => rsx! { div { class: "card", p { class: "muted", "No stories yet. Start one in the Editor." } } },
                        Some(Err(message)) => rsx! { div { class: "card", p { class: "state error", "Could not load stories: {message}" } } },
                        _ => rsx! { div { class: "card", p { class: "state", "Loading stories…" } } },
                    }
                }
                div { class: "dash-col",
                    MiniCalendar {}
                    div { class: "card widget",
                        div { class: "card-h", h3 { "In the newsroom" } }
                        match &*feed.read_unchecked() {
                            Some(Ok(Some(posts))) if !posts.is_empty() => rsx! {
                                ul { class: "rowlist",
                                    for post in posts.iter().take(5) {
                                        li { key: "{post.id}", class: "rowitem",
                                            span { class: "av soft", "{post.kind.chars().next().unwrap_or('•').to_uppercase().to_string()}" }
                                            div { class: "grow",
                                                div { class: "t", "{post.content}" }
                                                div { class: "s", "{post.kind} · \u{2665} {post.likes}" }
                                            }
                                        }
                                    }
                                }
                                Link { to: Route::Feed {}, class: "linklike", "Open feed \u{2192}" }
                            },
                            Some(Ok(Some(_))) => rsx! { p { class: "muted", "The feed is quiet." } },
                            _ => rsx! { p { class: "state", "Loading…" } },
                        }
                    }
                    div { class: "card widget",
                        div { class: "card-h", h3 { "Jump in" } }
                        div { class: "jump-grid",
                            Link { to: Route::Editor {}, class: "ghost", Icon { name: "plus" } "New story" }
                            Link { to: tasks_route(&scope.read()), class: "ghost", Icon { name: "tasks" } "Task board" }
                            Link { to: planning_route(&scope.read()), class: "ghost", Icon { name: "calendar" } "Planning" }
                        }
                    }
                }
            }
        }
    }
}

/// The pipeline stages shown on the dashboard pulse, `(workflow_state, label)`.
const PIPELINE_STAGES: [(&str, &str); 6] = [
    ("reporting", "Reporting"),
    ("drafting", "Drafting"),
    ("desk_review", "Desk review"),
    ("verification", "Verification"),
    ("copy_standards", "Copy & standards"),
    ("ready", "Ready"),
];

/// The badge colour tone for a workflow state, so the pipeline reads at a glance:
/// green when ready, amber in review, terracotta while being made, grey when parked.
fn stage_tone(state: &str) -> &'static str {
    match state {
        "ready" => "success",
        "desk_review" | "verification" | "copy_standards" => "warning",
        "parked" | "archived" => "muted",
        _ => "brand",
    }
}

/// Human label for a workflow state (falls back to a de-underscored, capitalized form).
fn stage_label(state: &str) -> String {
    PIPELINE_STAGES
        .iter()
        .find(|(key, _)| *key == state)
        .map_or_else(
            || {
                let mut s = state.replace('_', " ");
                if let Some(first) = s.get_mut(0..1) {
                    first.make_ascii_uppercase();
                }
                s
            },
            |(_, label)| (*label).to_owned(),
        )
}

/// Builds `(area_path, line_path)` for an SVG area chart over a 0..100 box from a
/// series of counts — the real pipeline-stage numbers. Empty/zero series yields a
/// flat baseline.
fn area_paths(counts: &[usize]) -> (String, String) {
    use std::fmt::Write as _;
    let n = counts.len();
    if n == 0 {
        return ("M0 100 L100 100 Z".to_owned(), "M0 100 L100 100".to_owned());
    }
    let max = counts.iter().copied().max().unwrap_or(1).max(1) as f64;
    let point = |i: usize| -> (f64, f64) {
        let x = if n > 1 { i as f64 / (n - 1) as f64 * 100.0 } else { 50.0 };
        let y = 92.0 - (counts[i] as f64 / max) * 74.0;
        (x, y)
    };
    let mut line = String::new();
    for i in 0..n {
        let (x, y) = point(i);
        let _ = write!(line, "{}{x:.1} {y:.1}", if i == 0 { "M" } else { " L" });
    }
    let mut area = line.clone();
    let (lastx, _) = point(n - 1);
    let (firstx, _) = point(0);
    let _ = write!(area, " L{lastx:.1} 100 L{firstx:.1} 100 Z");
    (area, line)
}

/// Two-letter initials from a title, for the row avatar chip.
fn initials(title: &str) -> String {
    let letters: String = title
        .split_whitespace()
        .take(2)
        .filter_map(|word| word.chars().next())
        .collect();
    if letters.is_empty() {
        "·".to_owned()
    } else {
        letters.to_uppercase()
    }
}

/// Headline stat cards from the dashboard summary: the first numeric fields,
/// humanized. Flexible so it survives summary-schema changes.
#[component]
fn StatRow(summary: serde_json::Value) -> Element {
    let mut stats: Vec<(String, String, i64)> = Vec::new();
    // The summary is `{ metrics: { <name>: { value, .. }, .. }, .. }` — one headline
    // number per metric card. The raw metric key also picks the card's icon.
    if let Some(metrics) = summary.get("metrics").and_then(serde_json::Value::as_object) {
        for (key, metric) in metrics {
            if let Some(n) = metric.get("value").and_then(serde_json::Value::as_i64) {
                stats.push((key.clone(), key.replace('_', " "), n));
            }
        }
    }
    stats.truncate(5);
    rsx! {
        div { class: "stat-row",
            for (key , label , n) in stats {
                {
                    let tag: String = label
                        .split_whitespace()
                        .take(2)
                        .filter_map(|w| w.chars().next())
                        .collect::<String>()
                        .to_uppercase();
                    rsx! {
                        div { key: "{key}", class: "stat",
                            span { class: "stat-tag", "{tag}" }
                            div { class: "k", "{label}" }
                            div { class: "n", "{n}" }
                        }
                    }
                }
            }
        }
    }
}

/// Picks a card icon from a metric's key, so each stat reads at a glance. Falls
/// back to a neutral grid glyph for anything unmapped.
#[allow(dead_code)] // retained for a possible icon variant; StatRow uses letter tags (comp).
fn stat_icon(key: &str) -> &'static str {
    let k = key.to_ascii_lowercase();
    if k.contains("stor") {
        "stories"
    } else if k.contains("review") || k.contains("verif") || k.contains("check") {
        "tasks"
    } else if k.contains("pitch") {
        "feed"
    } else if k.contains("correct") {
        "bell"
    } else if k.contains("publish") || k.contains("live") || k.contains("released") {
        "analytics"
    } else if k.contains("task") || k.contains("assign") {
        "editor"
    } else if k.contains("team") || k.contains("people") || k.contains("member") {
        "team"
    } else {
        "grid"
    }
}

#[component]
/// The left "brand canvas" shared by the auth screens: the wordmark, a fine-line
/// compass-star registration mark over faint crosshair guides, and a legal line.
/// Dark in both themes (it uses the sidebar tokens), so it keeps the drama while
/// the form panel beside it follows the theme.
