    #[cfg(feature = "web")]
    fn form_encode(value: &str) -> String {
        let mut encoded = String::with_capacity(value.len());
        for byte in value.bytes() {
            match byte {
                b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                    encoded.push(byte as char);
                }
                b' ' => encoded.push('+'),
                other => {
                    const HEX: &[u8; 16] = b"0123456789ABCDEF";
                    encoded.push('%');
                    encoded.push(HEX[(other >> 4) as usize] as char);
                    encoded.push(HEX[(other & 0x0f) as usize] as char);
                }
            }
        }
        encoded
    }

    #[cfg(feature = "web")]
    pub async fn sign_in(
        username: String,
        password: String,
    ) -> Result<(String, Option<String>, IdentityUser), String> {
        use gloo_net::http::Request;
        let body = format!(
            "username={}&password={}",
            form_encode(&username),
            form_encode(&password)
        );
        let response = Request::post("/api/v1/auth/token")
            .header("content-type", "application/x-www-form-urlencoded")
            .body(body)
            .map_err(|error| error.to_string())?
            .send()
            .await
            .map_err(|error| error.to_string())?;
        if response.status() == 401 {
            return Err("Incorrect email/handle or password.".to_owned());
        }
        if !response.ok() {
            return Err(format!("Sign-in failed ({}).", response.status()));
        }
        let tokens: IssuedTokens = response.json().await.map_err(|error| error.to_string())?;
        let me = Request::get("/api/v1/users/me")
            .header("authorization", &format!("Bearer {}", tokens.access_token))
            .send()
            .await
            .map_err(|error| error.to_string())?;
        if !me.ok() {
            return Err(format!("Could not load your account ({}).", me.status()));
        }
        let user: IdentityUser = me.json().await.map_err(|error| error.to_string())?;
        Ok((tokens.access_token, tokens.refresh_token, user))
    }

    #[cfg(not(feature = "web"))]
    #[allow(clippy::unused_async)] // Signature must match the browser variant awaited by callers.
    pub async fn sign_in(
        _username: String,
        _password: String,
    ) -> Result<(String, Option<String>, IdentityUser), String> {
        Err("sign-in runs in the browser".to_owned())
    }

