    /// Rotates an endpoint's signing secret, returning the new `whsec_…` value once.
    #[cfg(feature = "web")]
    pub async fn rotate_webhook_secret(access_token: String, id: String) -> Result<String, String> {
        use gloo_net::http::Request;
        let response = Request::post(&format!("/api/v1/webhooks/endpoints/{id}/rotate-secret"))
            .header("authorization", &format!("Bearer {access_token}"))
            .send()
            .await
            .map_err(|e| e.to_string())?;
        if !response.ok() {
            return Err(format!("rotate failed ({})", response.status()));
        }
        let body: serde_json::Value = response.json().await.map_err(|e| e.to_string())?;
        body.get("secret")
            .and_then(|s| s.as_str())
            .map(std::borrow::ToOwned::to_owned)
            .ok_or_else(|| "missing secret in response".to_owned())
    }
