    /// Answers a desk invitation. `accept` picks between the two legacy routes,
    /// which differ only in the boolean they hand `respond_to_invitation`.
    ///
    /// Accepting creates the membership, so the caller must reload the viewer's
    /// sectors afterwards — the switcher is built from exactly that list.
    #[cfg(feature = "web")]
    pub async fn respond_to_invitation(
        access_token: String,
        invitation_id: String,
        accept: bool,
    ) -> Result<(), String> {
        let verb = if accept { "accept" } else { "decline" };
        send_json(
            &access_token,
            "POST",
            &format!("/api/v1/invitations/{invitation_id}/{verb}"),
            &serde_json::Value::Null,
        )
        .await
    }

