    #[cfg(feature = "web")]
    pub async fn save_story(
        access_token: String,
        id: String,
        title: String,
        dek: String,
        blocks: Vec<BodyBlock>,
        topics: Vec<String>,
    ) -> Result<(), String> {
        use gloo_net::http::Request;
        // The body PATCHes as the legacy block array `[{ "type", "text" }]`; `tags`
        // carries the selected IPTC Media Topic qcodes.
        let body = serde_json::json!({
            "title": title,
            "dek": dek,
            "body": serde_json::to_value(&blocks).unwrap_or_else(|_| serde_json::Value::Array(Vec::new())),
            "tags": topics,
        })
        .to_string();
        let response = Request::patch(&format!("/api/v1/stories/{id}"))
            .header("authorization", &format!("Bearer {access_token}"))
            .header("content-type", "application/json")
            .body(body)
            .map_err(|error| error.to_string())?
            .send()
            .await
            .map_err(|error| error.to_string())?;
        if response.ok() {
            Ok(())
        } else {
            Err(format!("status {}", response.status()))
        }
    }

