    #[cfg(feature = "web")]
    async fn get_json<T: serde::de::DeserializeOwned>(access_token: &str, path: &str) -> Result<T, String> {
        use gloo_net::http::Request;
        let response = Request::get(path)
            .header("authorization", &format!("Bearer {access_token}"))
            .send()
            .await
            .map_err(|error| error.to_string())?;
        if !response.ok() {
            return Err(format!("request failed ({})", response.status()));
        }
        response.json().await.map_err(|error| error.to_string())
    }

    #[cfg(feature = "web")]
    pub async fn create_story(
        access_token: String,
        slug: String,
        title: String,
        desk_id: Option<String>,
        sub_sector_id: Option<String>,
    ) -> Result<String, String> {
        use gloo_net::http::Request;
        // `desk_id` binds the story to a sector so it appears in that workspace's
        // stories, dashboard and analytics. Omitted (org-level) stories surface only
        // in org-wide search, which is the desk-less state we do not want by default.
        // `sub_sector_id` files it under an industry within that sector (optional).
        let body = serde_json::json!({ "slug": slug, "title": title, "desk_id": desk_id, "sub_sector_id": sub_sector_id }).to_string();
        let response = Request::post("/api/v1/stories")
            .header("authorization", &format!("Bearer {access_token}"))
            .header("content-type", "application/json")
            .body(body)
            .map_err(|error| error.to_string())?
            .send()
            .await
            .map_err(|error| error.to_string())?;
        if !response.ok() {
            return Err(format!("status {}", response.status()));
        }
        let value: serde_json::Value = response.json().await.map_err(|error| error.to_string())?;
        value
            .get("id")
            .and_then(serde_json::Value::as_str)
            .map(ToOwned::to_owned)
            .ok_or_else(|| "no id in response".to_owned())
    }

