    /// Admin directly sets a user's password.
    #[cfg(feature = "web")]
    pub async fn admin_set_password(access_token: String, user_id: String, new_password: String) -> Result<serde_json::Value, String> {
        use gloo_net::http::Request;
        let response = Request::post(&format!("/api/v1/users/{user_id}/set-password"))
            .header("authorization", &format!("Bearer {access_token}"))
            .header("content-type", "application/json")
            .body(serde_json::json!({ "new_password": new_password }).to_string())
            .map_err(|error| error.to_string())?
            .send()
            .await
            .map_err(|error| error.to_string())?;
        if !response.ok() {
            let status = response.status();
            let detail = response.json::<serde_json::Value>().await.ok()
                .and_then(|v| v.get("detail").and_then(|d| d.as_str().map(str::to_owned)))
                .unwrap_or_else(|| format!("status {status}"));
            return Err(detail);
        }
        response.json::<serde_json::Value>().await.map_err(|error| error.to_string())
    }

