    /// Snoozes an item for `hours`. The endpoint requires an explicit
    /// `snoozed_until` instant rather than a duration, so the deadline is computed
    /// here from the browser clock and sent as RFC 3339.
    #[cfg(feature = "web")]
    pub async fn snooze_attention(
        access_token: String,
        fingerprint: String,
        hours: f64,
    ) -> Result<(), String> {
        let until_ms = js_sys::Date::now() + hours * 3_600_000.0;
        let until = js_sys::Date::new(&js_sys::Number::from(until_ms).into())
            .to_iso_string()
            .as_string()
            .ok_or("could not format the snooze deadline")?;
        let encoded = form_encode(&fingerprint);
        send_json(
            &access_token,
            "POST",
            &format!("/api/v1/attention/{encoded}/snooze"),
            &serde_json::json!({ "snoozed_until": until }),
        )
        .await
    }

