    /// category today; the block body is not yet decomposed.
    #[cfg(feature = "web")]
    pub async fn search(access_token: String, query: String) -> Result<Vec<SearchHit>, String> {
        let encoded = form_encode(&query);
        let value: serde_json::Value =
            get_json(&access_token, &format!("/api/v1/search?q={encoded}")).await?;
        let items = value
            .get("results")
            .or_else(|| value.get("items"))
            .cloned()
            .unwrap_or(value);
        serde_json::from_value(items).map_err(|error| error.to_string())
    }

