    /// Files a new pitch from the editorial-intake form. `body` is the JSON
    /// accepted by `POST /pitches` (headline, summary, angle, desk_id, priority,
    /// expected_format, key_questions, likely_sources, risks, target_at).
    #[cfg(feature = "web")]
    pub async fn create_pitch(
        access_token: String,
        body: serde_json::Value,
    ) -> Result<PitchRow, String> {
        use gloo_net::http::Request;
        let response = Request::post("/api/v1/pitches")
            .header("authorization", &format!("Bearer {access_token}"))
            .header("content-type", "application/json")
            .body(body.to_string())
            .map_err(|error| error.to_string())?
            .send()
            .await
            .map_err(|error| error.to_string())?;
        if !response.ok() {
            return Err(format!("Pitch failed ({})", response.status()));
        }
        response.json::<PitchRow>().await.map_err(|error| error.to_string())
    }

