    /// The audit trail, newest first, optionally narrowed by entity type or
    /// action. The backend caps `limit`; this passes it through explicitly rather
    /// than relying on its default so the page size is visible at the call site.
    #[cfg(feature = "web")]
    pub async fn audit_log(
        access_token: String,
        entity_type: Option<String>,
        limit: u32,
    ) -> Result<Vec<AuditRow>, String> {
        let path = match entity_type.filter(|value| !value.is_empty()) {
            Some(entity) => format!("/api/v1/audit?limit={limit}&entity_type={entity}"),
            None => format!("/api/v1/audit?limit={limit}"),
        };
        get_json(&access_token, &path).await
    }

