    /// This is resolver step 5, and it is the only grant that can be *desk-scoped*
    /// — which is what makes "editor-in-chief, but only in Investigations"
    /// expressible at all. `scope_type` follows `scope_id`: a desk id means
    /// `"desk"`, its absence means `"global"`.
    #[cfg(feature = "web")]
    pub async fn assign_role(
        access_token: String,
        user_id: String,
        role_key: String,
        scope_id: Option<String>,
        ends_at: Option<String>,
        reason: Option<String>,
    ) -> Result<(), String> {
        let body = serde_json::json!({
            "role_key": role_key,
            "scope_type": if scope_id.is_some() { "desk" } else { "global" },
            "scope_id": scope_id,
            "ends_at": ends_at,
            "reason": reason,
        });
        send_json(
            &access_token,
            "POST",
            &format!("/api/v1/users/{user_id}/role-assignments"),
            &body,
        )
        .await
    }

