    /// Publishes, or schedules, a release of a specific version.
    ///
    /// This is the act the publish gate guards: the backend re-runs every blocker,
    /// refuses anything but the latest version, and requires `releases.publish` in
    /// the story's own sector. A `scheduled_at` in the future files the release as
    /// due rather than publishing it now.
    #[cfg(feature = "web")]
    pub async fn create_release(
        access_token: String,
        story_id: String,
        version_id: String,
        channels: Vec<String>,
        scheduled_at: Option<String>,
        embargo_until: Option<String>,
        expires_at: Option<String>,
    ) -> Result<(), String> {
        let body = serde_json::json!({
            "version_id": version_id,
            "channels": channels,
            "scheduled_at": scheduled_at,
            "embargo_until": embargo_until,
            "expires_at": expires_at,
        });
        send_json(&access_token, "POST", &format!("/api/v1/stories/{story_id}/releases"), &body)
            .await
    }

