    /// Schedules a coverage event.
    ///
    /// `starts_at` is sent as RFC 3339 because that is what the backend parses; a
    /// `<input type="date">` yields a bare `YYYY-MM-DD`, so the caller widens it
    /// to midnight UTC. An empty date is sent as `null`, which files the event in
    /// the unscheduled panel rather than guessing a day.
    #[cfg(feature = "web")]
    pub async fn create_coverage_event(
        access_token: String,
        title: String,
        date: Option<String>,
        location: Option<String>,
    ) -> Result<(), String> {
        let starts_at = date.map(|day| format!("{day}T00:00:00Z"));
        let body = serde_json::json!({
            "title": title,
            "starts_at": starts_at,
            "location": location,
        });
        send_json(&access_token, "POST", "/api/v1/coverage-events", &body).await
    }

