    /// Picks a multipart boundary that cannot appear inside the payload.
    ///
    /// A boundary that collides with the file's own bytes would split the part
    /// early and corrupt the upload — rare, but silent when it happens, and
    /// binary uploads are exactly where it is plausible. Extending the candidate
    /// until it is absent is cheap and removes the failure mode entirely; there
    /// is no randomness available in this build to lean on instead.
    #[cfg(feature = "web")]
    fn multipart_boundary(payload: &[u8]) -> String {
        let mut boundary = "meridian-boundary".to_owned();
        while payload.windows(boundary.len()).any(|window| window == boundary.as_bytes()) {
            boundary.push('-');
        }
        boundary
    }

    /// Uploads real bytes to the object store via `POST /assets/upload`.
    ///
    /// The endpoint is multipart (`file`, optional `story_id` / `alt_text`) and
    /// writes the object *before* the metadata row, so a failure here leaves no
    /// asset row pointing at bytes that do not exist.
    #[cfg(feature = "web")]
    pub async fn upload_asset(
        access_token: String,
        filename: String,
        content_type: String,
        bytes: Vec<u8>,
        alt_text: Option<String>,
    ) -> Result<AssetRow, String> {
        use gloo_net::http::Request;

        let boundary = multipart_boundary(&bytes);
        let mut body: Vec<u8> = Vec::with_capacity(bytes.len() + 512);
        body.extend_from_slice(format!("--{boundary}\r\n").as_bytes());
        body.extend_from_slice(
            format!("Content-Disposition: form-data; name=\"file\"; filename=\"{filename}\"\r\n")
                .as_bytes(),
        );
        body.extend_from_slice(format!("Content-Type: {content_type}\r\n\r\n").as_bytes());
        body.extend_from_slice(&bytes);
        body.extend_from_slice(b"\r\n");
        if let Some(alt) = alt_text.filter(|value| !value.trim().is_empty()) {
            body.extend_from_slice(format!("--{boundary}\r\n").as_bytes());
            body.extend_from_slice(
                b"Content-Disposition: form-data; name=\"alt_text\"\r\n\r\n".as_slice(),
            );
            body.extend_from_slice(alt.as_bytes());
            body.extend_from_slice(b"\r\n");
        }
        body.extend_from_slice(format!("--{boundary}--\r\n").as_bytes());

        let response = Request::post("/api/v1/assets/upload")
            .header("authorization", &format!("Bearer {access_token}"))
            .header("content-type", &format!("multipart/form-data; boundary={boundary}"))
            .body(js_sys::Uint8Array::from(body.as_slice()))
            .map_err(|error| error.to_string())?
            .send()
            .await
            .map_err(|error| error.to_string())?;
        if !response.ok() {
            return Err(format!("Upload failed ({}).", response.status()));
        }
        response.json().await.map_err(|error| error.to_string())
    }

