    /// Standard base64 (no line breaks) — enough to build `data:` image URLs
    /// without pulling in a dependency.
    #[cfg(feature = "web")]
    fn base64_encode(data: &[u8]) -> String {
        const T: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        let mut out = String::with_capacity(data.len().div_ceil(3) * 4);
        for chunk in data.chunks(3) {
            let b0 = chunk[0];
            let b1 = chunk.get(1).copied().unwrap_or(0);
            let b2 = chunk.get(2).copied().unwrap_or(0);
            out.push(T[(b0 >> 2) as usize] as char);
            out.push(T[(((b0 & 0x03) << 4) | (b1 >> 4)) as usize] as char);
            out.push(if chunk.len() > 1 { T[(((b1 & 0x0f) << 2) | (b2 >> 6)) as usize] as char } else { '=' });
            out.push(if chunk.len() > 2 { T[(b2 & 0x3f) as usize] as char } else { '=' });
        }
        out
    }

    /// Fetches an asset's bytes through the app's own origin and returns a
    /// `data:` URL. The strict `img-src 'self' data:` CSP blocks the object
    /// store's cross-origin host, so presigned URLs never render in an `<img>`;
    /// a same-origin fetch + `data:` URL displays everywhere.
    #[cfg(feature = "web")]
    pub async fn asset_data_url(access_token: String, asset_id: String) -> Result<String, String> {
        use gloo_net::http::Request;
        let response = Request::get(&format!("/api/v1/assets/{asset_id}/raw"))
            .header("authorization", &format!("Bearer {access_token}"))
            .send()
            .await
            .map_err(|error| error.to_string())?;
        if !response.ok() {
            return Err(format!("status {}", response.status()));
        }
        let content_type = response
            .headers()
            .get("content-type")
            .unwrap_or_else(|| "image/jpeg".to_owned());
        let bytes = response.binary().await.map_err(|error| error.to_string())?;
        Ok(format!("data:{content_type};base64,{}", base64_encode(&bytes)))
    }

