    /// The browser key holding the rotating refresh token.
    #[cfg(feature = "web")]
    const REFRESH_KEY: &str = "meridian.refresh_token";

    /// Persists the refresh token so a reload can restore the session. Only the
    /// refresh token is stored — never the access token, which is short-lived and
    /// stays in memory.
    #[cfg(feature = "web")]
    pub fn store_refresh_token(token: Option<&str>) {
        use gloo_storage::{LocalStorage, Storage};
        match token {
            Some(value) => {
                let _ = LocalStorage::set(REFRESH_KEY, value);
            }
            None => LocalStorage::delete(REFRESH_KEY),
        }
    }

    #[cfg(not(feature = "web"))]
    pub fn store_refresh_token(_token: Option<&str>) {}

    #[cfg(feature = "web")]
    #[must_use]
    pub fn stored_refresh_token() -> Option<String> {
        use gloo_storage::{LocalStorage, Storage};
        LocalStorage::get::<String>(REFRESH_KEY).ok().filter(|value| !value.is_empty())
    }

    #[cfg(not(feature = "web"))]
    #[must_use]
    pub fn stored_refresh_token() -> Option<String> {
        None
    }

    /// Exchanges a stored refresh token for a live session. The refresh rotates,
    /// so the replacement token is written back before returning; a rejected token
    /// clears storage so a stale value cannot loop.
    #[cfg(feature = "web")]
    pub async fn restore_session(
        refresh_token: String,
    ) -> Result<(String, Option<String>, IdentityUser), String> {
        use gloo_net::http::Request;
        let body = serde_json::json!({ "refresh_token": refresh_token }).to_string();
        let response = Request::post("/api/v1/auth/refresh")
            .header("content-type", "application/json")
            .body(body)
            .map_err(|error| error.to_string())?
            .send()
            .await
            .map_err(|error| error.to_string())?;
        if !response.ok() {
            store_refresh_token(None);
            return Err(format!("session expired ({})", response.status()));
        }
        let tokens: IssuedTokens = response.json().await.map_err(|error| error.to_string())?;
        store_refresh_token(tokens.refresh_token.as_deref());
        let me = Request::get("/api/v1/users/me")
            .header("authorization", &format!("Bearer {}", tokens.access_token))
            .send()
            .await
            .map_err(|error| error.to_string())?;
        if !me.ok() {
            store_refresh_token(None);
            return Err(format!("could not load your account ({})", me.status()));
        }
        let user: IdentityUser = me.json().await.map_err(|error| error.to_string())?;
        Ok((tokens.access_token, tokens.refresh_token, user))
    }

    #[cfg(not(feature = "web"))]
    #[allow(clippy::unused_async)]
    pub async fn restore_session(
        _refresh_token: String,
    ) -> Result<(String, Option<String>, IdentityUser), String> {
        Err("session restore runs in the browser".to_owned())
    }

