    /// Revokes one other device's session by id. The backend gates it to the
    /// caller's own sessions, so this can only end the account holder's devices.
    #[cfg(feature = "web")]
    pub async fn revoke_session(access_token: String, session_id: String) -> Result<(), String> {
        use gloo_net::http::Request;
        let response = Request::delete(&format!("/api/v1/auth/sessions/{session_id}"))
            .header("authorization", &format!("Bearer {access_token}"))
            .send()
            .await
            .map_err(|error| error.to_string())?;
        if response.ok() {
            Ok(())
        } else {
            Err(format!("status {}", response.status()))
        }
    }

