    /// Requests a password-reset token for an email. In dev
    /// (`MERIDIAN_EXPOSE_RESET_TOKENS=true`) the token is returned so the flow can
    /// be completed without an email channel; otherwise `Ok(None)`.
    #[cfg(feature = "web")]
    pub async fn request_password_reset(email: String) -> Result<Option<String>, String> {
        use gloo_net::http::Request;
        let body = serde_json::json!({ "email": email }).to_string();
        let response = Request::post("/api/v1/auth/password-reset/request")
            .header("content-type", "application/json")
            .body(body)
            .map_err(|error| error.to_string())?
            .send()
            .await
            .map_err(|error| error.to_string())?;
        if !response.ok() {
            return Err(format!("status {}", response.status()));
        }
        let value: serde_json::Value = response.json().await.map_err(|error| error.to_string())?;
        Ok(value
            .get("reset_token")
            .and_then(serde_json::Value::as_str)
            .map(ToOwned::to_owned))
    }

    #[cfg(not(feature = "web"))]
    #[allow(clippy::unused_async)]
    pub async fn request_password_reset(_email: String) -> Result<Option<String>, String> {
        Err("runs in the browser".to_owned())
    }

