    /// Revokes the caller's session server-side, then clears the stored refresh
    /// token.
    ///
    /// Dropping the client-held tokens alone is not a sign-out: the rotating
    /// refresh token stays valid until it expires, so anything that captured it
    /// could still mint access tokens. `POST /auth/logout` revokes the access
    /// token's own session with reason `'logout'`.
    ///
    /// Storage is cleared whatever the server answers — a failed revoke must not
    /// leave the browser holding a token it believes it has surrendered — so this
    /// reports the outcome rather than gating the sign-out on it.
    #[cfg(feature = "web")]
    pub async fn sign_out(access_token: String) -> Result<(), String> {
        let revoked =
            send_json(&access_token, "POST", "/api/v1/auth/logout", &serde_json::Value::Null).await;
        store_refresh_token(None);
        revoked
    }

    #[cfg(not(feature = "web"))]
    #[allow(clippy::unused_async)]
    pub async fn sign_out(_access_token: String) -> Result<(), String> {
        store_refresh_token(None);
        Ok(())
    }

