#[cfg(test)]
mod helper_tests {
    use super::{
        channel_label, fm_short_date, fmt_when, local_input_to_rfc3339, rfc3339_to_local_input,
        status_label,
    };

    #[test]
    fn channel_label_titles_known_and_unknown_keys() {
        assert_eq!(channel_label("web"), "Web");
        assert_eq!(channel_label("website"), "Website");
        assert_eq!(channel_label("app_push"), "App push");
        assert_eq!(channel_label("newsletter"), "Newsletter");
        // Unknown keys are underscore-spaced and sentence-cased.
        assert_eq!(channel_label("social_wire"), "Social wire");
        assert_eq!(channel_label(""), "");
    }

    #[test]
    fn status_label_unslugs_underscores() {
        assert_eq!(status_label("partial_failure"), "partial failure");
        assert_eq!(status_label("scheduled"), "scheduled");
    }

    #[test]
    fn short_date_and_when_render_the_calendar_parts() {
        assert_eq!(fm_short_date("2026-08-05T14:30:00Z"), "5 Aug 2026");
        assert_eq!(fmt_when("2026-08-05T14:30:00Z"), "5 Aug 2026, 14:30");
        assert_eq!(fmt_when(""), "\u{2014}");
    }

    #[test]
    fn server_side_datetime_conversions_degrade_gracefully() {
        // Off the browser there is no clock, so the RFC-3339 -> input path just
        // trims to minute precision and the reverse path yields nothing.
        assert_eq!(rfc3339_to_local_input("2026-08-05T14:30:00Z"), "2026-08-05T14:30");
        assert_eq!(local_input_to_rfc3339("2026-08-05T14:30"), None);
    }
}
